-- ─────────────────────────────────────────────────────────────
--  THE OLD WEBSITE'S NEWS — part 4 of 7: 65 articles kept as drafts (not live)
--  Generated by scripts/import-old-news.py from Rich's export of the old WordPress database.
--  Run the news files in order, after the other files in supabase/legacy/ (SQL Editor → paste → Run), each once.
--
--  All 528 old articles: 186 league and competition articles from 2019 on go live, with their real dates.
--  The other 342 wait in Admin → News as drafts (Rich, round 30): Professional Snooker, CueViews,
--  Snooker Memories, and the old archive — whose articles all carry the date 1 January 2014 on the old site
--  (their real dates were lost long ago). Tick "Published" on any of them to put it on the website.
--  The text keeps its paragraphs, the opening paragraph and the pull quote. Pictures are not brought across
--  (Rich is sorting them): real-data/legacy/news-pictures.csv says which article had which picture.
--  None is "featured", so the News page and the banner keep showing the newest articles.
--  Nothing already on the website is changed. All one transaction.
-- ─────────────────────────────────────────────────────────────
begin;

do $$ begin
  if exists (select 1 from articles where slug in ('cueview-john-parrott-exclusive', 'cueview-john-virgo-exclusive', 'cueview-leighton-varcoe', 'cueview-mark-king-exclusive', 'cueview-martin-gould-exclusive')) then
    raise exception 'This part of the old news is already in: nothing to do.';
  end if;
end $$;

insert into categories (name, sort)
  select r.name, 100 + row_number() over (order by r.name) from (values
  ('Competitions'),
  ('Cue View'),
  ('League Meetings'),
  ('League News'),
  ('Match Reports'),
  ('Professional Snooker'),
  ('Snooker Memories')) r(name)
  where not exists (select 1 from categories c where lower(c.name) = lower(r.name));

create temp table _news (title text, slug text, category text, more_categories jsonb, excerpt text, lead text, quote_text text, body text, published_at date, is_published boolean, author text) on commit drop;
insert into _news values
  ('CUEVIEW - John Parrott Exclusive', 'cueview-john-parrott-exclusive', 'Cue View', '[]'::jsonb, 'I interrupted JV whilst he was busy reading the paper in the press room at the masters for this CueView, thankfully JV was more than happy to do it although he did complain a little that he was busy - hmmm ok John', null, '"Ronnie beating John Higgins in the masters final 10-3 simply flawless and unplayable snooker."', 'I interrupted JV whilst he was busy reading the paper in the press room at the masters for this CueView, thankfully JV was more than happy to do it although he did complain a little that he was busy - hmmm ok John

more STBS - What is your full name please JP - John Parrott STBS - Your Current Club/base JP - Don''t have one as I travel all the time for TV, BBC etc. STBS - Your Highest Break JP - 147 STBS - Are you Left/Right Handed or both JP - I am right handed STBS - Bio about yourself (in no more than 200 words) JP - Former UK, European and World Champion STBS - What was your first ever memory of snooker? JP - A small kids table in a friends house I was 6 years old STBS - At what age did you start playing snooker and why? JP - 12 years old and immediately hooked! STBS - What has been your greatest achievement in snooker? JP - World & Uk Champ in 1991 STBS - Who is the most famous professional player you have played or met? (can be modern or older era) JP - I have met and played nearly every player In the game of snooker STBS - Who is your favourite TV commentator? JP - Dennis Taylor STBS - What is your Favourite professional player and why? JP - Ronnie O''Sullivan in full swing genius at work! STBS - What has been the most memorable snooker match you have ever seen? JP - Ronnie beating John Higgins in the masters final 10-3 simply flawless and unplayable snooker. STBS -Who is the most under-rated player in professional snooker? JP - Graeme dott is the most under rated player. STBS - Funniest moment in your snooker experience? JP - Showing millions at home in a live demo how to break off and completely missing the pack STBS - Who is your bogey player? JP - Myself LOL STBS - Do you have any snooker ambitions you still have not achieved? JP - My only regret was not winning the masters - 3 finals lost to some bloke called Hendry! Images Courtesy of: Tai Chengzhe', '2014-01-01', false, 'Richard Pearson'),
  ('CUEVIEW - John Virgo Exclusive', 'cueview-john-virgo-exclusive', 'Cue View', '[]'::jsonb, 'Whilst at the Masters in January 2013 I caught up briefly with John Virgo who kindly agreed to do us a CueView', null, '"I won the UK championship in 1979 got to the semi finals of the worlds in the same year, and co-hosted ''Big Break''"', 'Whilst at the Masters in January 2013 I caught up briefly with John Virgo who kindly agreed to do us a CueView

more STBS - What is your full name please JV - John Trevor Virgo STBS - Your Current Club/base JV - Don''t have one as I travel all the time for TV, Legends etc STBS - Your Highest Break JV - 147 STBS - Are you Left/Right Handed or both JV - I am right handed STBS - Bio about yourself (in no more than 200 words) JV - I won the UK championship in 1979 got to the semi finals of the worlds in the same year, and co-hosted ''Big Break'' STBS - What was your first ever memory of snooker? JV - Watching Joe Davis on Grandstand STBS - At what age did you start playing snooker and why? JV - 15 years old after playing at the YMCA club in Manchester STBS - What has been your greatest achievement in snooker? JV - Winning the UK championship STBS - Who is the most famous professional player you have played or met? (can be modern or older era) JV - I have met every player In the game of snooker STBS - Who is your favourite TV commentator? JV - Ted Lowe STBS - What is your Favourite professional player and why? JV - Jimmy White, great friend and sportsman STBS - What has been the most memorable snooker match you have ever seen? JV - Taylor - Davis 1985 world final STBS -Who is the most under-rated player in professional snooker? JV - Graeme dott is the most under rated player. STBS - Funniest moment in your snooker experience? JV - The referee dropping the pink into the reds STBS - Who is your bogey player? JV - Tony Meo was always my bogey player STBS - Do you have any snooker ambitions you still have not achieved? JV - Not really:-) Images Courtesy of: Tai Chengzhe', '2014-01-01', false, 'Richard Pearson'),
  ('CUEVIEW - Leighton Varcoe', 'cueview-leighton-varcoe', 'Cue View', '[]'::jsonb, 'The still playing legend that is Mevagissey''s one and only Leighton Varvoe shares his CUEVIEw with us', null, '"Playing in the final of Pot Black (Plymouth) cup doubles diamond snooker tournament 1981 made a 69 break in frame 3. The referee a welshman called Leighton Rees (one of the worlds top darts players and ex world champion) this brought a big big laugh from the audience watching and then I went on to win the next 3 frames and the match 4-2 against welsh professional (Wayne Jones) after being 2-0 behind"', 'The still playing legend that is Mevagissey''s one and only Leighton Varvoe shares his CUEVIEw with us

more For more interesting articles and memories please read Leighton''s memories, if you are interested in adding some of your own you can also do this via the online form, please click here to view STBS - What is your full name please LV - My full name is Varcoe, Henry, Leighton STBS - Your Current Club/base LV - Mevagissey Social Club STBS - Your Highest Break (if 147 how many) LV - My highest break is 137 STBS - Are you Left/Right Handed or both LV - Just right handed STBS - Bio about yourself (in no more than 200 words) LV - Started watching snooker & billiards at an early age at Mevagissey club. Went to the club with my dad who was a very good billiards player & then at home learnt the idea of snooker playing on a large wooden tray with large marbles as balls and a walking stick as a cue with a rubber bung as a tip and developed my skills from there. Advanced to 3/4 size table (Jonathon Barrons) and at 15 years old joined Mevagissey Social Club where all my age group played and then developed into a most formidable team. From the Mid 1950''s until 1975 (as records prove) but as a team we had such extra strengths in our reserves like all great players, and if you look up the records from the mid 1950''s to 1975 we have a tremendous record of achievement. At the foot of this interview see the achievements. STBS - What was your first ever memory of snooker? LV - Watching Jonathon Barron at a very young age knocking in breaks unto 80 in a 3/4 table in a big room over his Brookes Antique shop in Mevagissey STBS - At what age did you start playing snooker and why? LV - Approx 6 years old at mega social club used to go and watch my dad who was a very good billiards player, at home played on a big wood tray with big marbles STBS - What has been your greatest achievement in snooker? LV - Cornish Individual Champion 1975 England International 1969, Cornwall County player 1960 to 1992 TV Debut 1975, Winning British Isles Royal British Legion Championship Individual & Pairs, representing Tywardreath RBL club (individual winner in 1973 & runner up 1975, Pairs winner 1971/72/73 Runner up 1975. Pairs once with Graham Miles & twice with John Cowlmy. STBS - Who is the most famous professional player you have played or met? (can be modern or older era) LV - Steve Davis have met him a few times and played against him at a holiday Inn on Plymouth Hoe 1983 in front of 800 spectators STBS - Who is your favourite TV commentator? LV - Ted Lowe (whispering) have met him and was interviewed by him in 1975 on TV debut from Hotel Leofric (Coventry) STBS - What is your Favourite professional player and why? LV - Steve Davis (king of the 80''s) really like his style of play and also what a great ambassador for the sport of snooker STBS - What has been the most memorable snooker match you have ever seen? LV - Watching on TV 1985 Steve Davis losing to Dennis Taylor after being lots of frames ahead STBS - Who is the best player in the league? LV - Over a long period of time Jonathan Barron (MSC) Present day Barrie McIntosh STBS -Who is the most underated player in the league? LV - In my view David Rundle of Bugle WMC STBS - Funniest moment in your snooker experience? LV - Playing in the final of Pot Black (Plymouth) cup doubles diamond snooker tournament 1981 made a 69 break in frame 3. The referee a welshman called Leighton Rees (one of the worlds top darts players and ex world champion) this brought a big big laugh from the audience watching and then I went on to win the next 3 frames and the match 4-2 against welsh professional (Wayne Jones) after being 2-0 behind STBS - Do you have any snooker ambitions you still have not achieved? LV - Snooker playing wise (would like to make another 100 break) haven''t made one for at least 20 years + before I''m taken to pastures new STBS - Who is your bogey player? LV - In later stages of life John Wilson of Tywardreath RBL Club

ACHIEVEMENTS

1956- Cornish Youth Champion & St Blazey Youth champion 1973- Royal British Legion clubs british isles club individual champion 1973- & Runner up 1975 1971//72/73 Pairs Champion & Runner up 1974 - Represented Tywardreath RBL club 1975 Cornish Individual champion & runner up 1965/67/83 Cornish Pairs champion 1960-1969 10 years undefeated with Jonathan Barron 1969 England International v Wales in Wales Cornwall County Player 1960 to 1992 Cornwall County Billiards Player (4 times) Cornwall 5 aside Inter club champions 12 times - Joe Davis Inter town 7 aside 10 times Cornwall 3 pairs aside champion 4 times Cornwall 3 aside billiards champion 4 times Cornish Individual Billiards Championship runner up 1971 Cornish break prize holder several times St Blazey & District league champions a record number of times Individual snooker twice plus pairs and team pairs Break prize holder, 3 pairs aside Team Handicap and Guardian seated handicap 1975 British Isles 2 aside tournament over 1000 2 aside teams entered to get to the final stages Jonathan and myself had to win the Cornwall area and then the South West area after that a regional final in the regional final we played against Patsy Fagan. (well known professional and his partner 4-0 to reach the final stages to be played at the hotel ''Leofric'' Coventry (June 1975) live on TV. We progressed to the semi-finals and had to play the welsh champions and although we drew the match 3-3 we lost on aggregate points by 20 points (at the time it was rather disappointing). Done well against professionals of the day when they were touring the South West beating such names as John Spencer 3-1/Patsy Fagan 2-1 Fred Davis1-0 Alex Higgins 2-1 Paul Medati 1-0 Marcel Gavreaux of Canada 3-0, Jack Karnham 2-0 Terry Whitedread 3-1 narrowly loosing to John Pulman/Graham Miles/Willie Thorne/Steve Davis and Kirk Stephens/Doug Mountjoy. Done well in the south west money tournament from 1977 to 1982 (winning several thousand of Miuntjo. Beat pro (welsh) Wayne Jones 4-2 in 1982 after being 2-0 behind only played 3 times Played at Pot Black club Plymouth over 2 days against for several years winning it in 1982 other famous names to win this are Neal Foulds 1981 and Tony Drago 1983, lots of prize money and a big trophy Thank you Leighton for chatting with us, we look forward to seeing and reading your memories on the website in the coming months. Images Courtesy of: Richard Pearson', '2014-01-01', false, 'Richard Pearson'),
  ('CUEVIEW - Mark King Exclusive', 'cueview-mark-king-exclusive', 'Cue View', '[]'::jsonb, 'Today Mark King joined our ever growing list of illustrious professional CueViews, Mark dropped everything to do this interview even though he was already at the UK champs practising for his opening match against MJ…', null, '"I have played snooker for over 25 years and have been a pro for 22 years, have reached 2 major finals and a few semi finals, hoping to win a ranking event one day.i have a wonderful wife and 3 brilliant children."', 'Today Mark King joined our ever growing list of illustrious professional CueViews, Mark dropped everything to do this interview even though he was already at the UK champs practising for his opening match against MJ Williams - what a guy.

more STBS - What is your full name please MK - Mark Anthony King STBS - Your Current Club/base MK - I play at Q ball snooker club chelmsford STBS - Your Highest Break MK - I have had more than 20 147s STBS - Are you Left/Right Handed or both MK - I am left handed STBS - Bio about yourself (in no more than 200 words) MK - I have played snooker for over 25 years and have been a pro for 22 years,have reached 2 major finals and a few semi finals, hoping to win a ranking event one day.i have a wonderful wife and 3 brilliant children. STBS - What was your first ever memory of snooker? MK - Watching Steve Davis vs Alex Higgins on TV STBS - At what age did you start playing snooker and why? MK - I started playing at 10 years old STBS - What has been your greatest achievement in snooker? MK - My best achievement so far has to be when I beat Jimmy White at Wembley 6-5 with all my family there STBS - Who is the most famous professional player you have played or met? (can be modern or older era) MK - I have met every player In the game of snooker STBS - Who is your favourite TV commentator? MK - Neal founds is my fav commentator STBS - What is your Favourite professional player and why? MK - I don''t have a favourite player, I get on with everybody STBS - What has been the most memorable snooker match you have ever seen? MK - Best match is when Stephen Hendry beat Jimmy White 18-14 STBS -Who is the most under-rated player in professional snooker? MK - Graeme dott is the most under rated player. STBS - Funniest moment in your snooker experience? MK - Funniest moment in snooker for me is when I was at the masters and I came out dancing STBS - Who is your bogey player? MK - I don''t have a bogey player STBS - Do you have any snooker ambitions you still have not achieved? MK - My ambition is to win a ranking event still Images Courtesy of: Action Images', '2014-01-01', false, 'Richard Pearson'),
  ('CUEVIEW - Martin Gould Exclusive', 'cueview-martin-gould-exclusive', 'Cue View', '[]'::jsonb, 'Martin @Gouldyballs147 Gould is the latest professional to do an exclusive CueView interview with us', null, '"I''ve had some memorable matches with Robertson, Murphy and Fu to name some but for me it gotta be Hendry vs O''Sullivan at the Liverpool Victoria Charity Challenge final I was in crowd for that as i had won vip tickets from Pot Black Magazine"', 'Martin @Gouldyballs147 Gould is the latest professional to do an exclusive CueView interview with us

more STBS - What is your full name please MG - Martin Gould STBS - Your Current Club/base MG - Totteridge & Whetstone Snooker Club STBS - Your Highest Break MG - I''ve had 73 147s STBS - Are you Left/Right Handed or both MG - I am right handed STBS - Bio about yourself (in no more than 200 words) MG - Hi i am Martin Gould pro snooker player down to earth friendly guy always has time for fans hard working dedicated snooker player who loves the game very attacking player who loves causing a stir on the green baize. STBS - What was your first ever memory of snooker? MG - 1st memory is being a baby and watching pot black with my dad and watching world champs for 2 weeks not missing a ball being hit STBS - At what age did you start playing snooker and why? MG - I was about 2 & a half years old when parents got me a tiny table then as i got bit older my sister brought me 6ft table which i never came off from STBS - What has been your greatest achievement in snooker? MG - My best achievement, i don''t think I`ve had it yet personally I`ve won a PTC just recently which was 1st major event i also won Power Snooker beating Trump, Bingham, Selby and Ronnie in the final also i''m a 2 time english amateur champion and european under 18 8 ball pool champion. I still think there is something big waiting around corner for me STBS - Who is the most famous professional player you have played or met? (can be modern or older era) MG - Well i been lucky enough to play Mr Hendry, O''Sullivan, Higgins & Davis but meeting Alex Higgins was a great experience STBS - Who is your favourite TV commentator? MG - Neal Foulds & Dennis Taylor would be my favourite commentators STBS - What is your Favourite professional player and why? MG - My fav player would be Hendry his attacking style will to win was immense STBS - What has been the most memorable snooker match you have ever seen? MG - I''ve had some memorable matches with Robertson, Murphy and Fu to name some but for me it gotta be Hendry vs O''Sullivan at the Liverpool Victoria Charity Challenge final i was in crowd for that as i had won vip tickets from pot black magazine STBS -Who is the most under-rated player in professional snooker? MG - Underrated players ooh thats tough Jamie Jones, Michael White and Jack Lisowski all come to mind STBS - Funniest moment in your snooker experience? MG - Funniest moment would be Jan Verhas stinking the booth out in sheffield during my world qualifier a couple of years ago STBS - Who is your bogey player? MG - My bogey player at current time is Shaun Murphy he seems to like playing me STBS - Do you have any snooker ambitions you still have not achieved? MG - My ambitions is to of course win world title be in top 8 and win many ranking events and participate in the later stages of events Images Courtesy of: Monique Limbos & Action Images', '2014-01-01', false, 'Richard Pearson'),
  ('CUEVIEW - Michaela Tabb Exclusive', 'cueview-michaela-tabb-exclusive', 'Cue View', '[]'::jsonb, 'Michaela Tabb, much loved female snooker referee and jolly nice Scottish lass phoned us today for an exclusive St Blazey Snooker Interview.', null, 'I did the shanghai masters final as well this year which was unbelievable again John Higgins loosing 7-2 in the first session but making a 147 everyone had written him off but I knew that it could be long evening you should never write John Higgins off, how he does it god knows and the bottle he has unbelievable. "', 'Michaela Tabb, much loved female snooker referee and jolly nice Scottish lass phoned us today for an exclusive St Blazey Snooker Interview.

more To be fair I have been bugging Michaela for months now to do this on twitter and email, she is a very busy lady always jet setting and travelling round the country on trains, not to mention looking after her family. But we finally nailed her down and here is the interview you have all been waiting for - enjoy. STBS - What is your full name please MT - Michaela Tabb STBS - Bio about yourself (in no more than 200 words) MT - Michaela Tabb was born on 11 December 1967 in Bath, England and moved to Scotland when she was 3years old. She had a successful amateur career playing 8 ball pool prior to beginning her career as a professional referee. Michaela began playing competitively in 1991 at the age of 23. A distinguished amateur career where she played for the Scottish Ladies 8 Ball Pool Team from 1992-2003, Michaela captained them to two consecutive Grand Slams in 1997 and 1998. She also had a successful singles career, winning the UK Women’s Singles title in 1997 and the European Ladies 8 Ball Pool Championships in Gibraltar in 1998. During the mid 1990s Michaela began refereeing at amateur 8 ball pool tournaments run by herself and her husband Ross McInnes. And it was Ross who encouraged Michaela to pursue refereeing at a professional level. In 1997 after giving birth to her first son Morgan, Michaela made her debut as a professional referee at the Matchroom Sport''s St Andrew''s Cup that was to be held in Glasgow. After Ross suggested Michaela as a referee for the event, Michaela sent a copy of her CV and a photograph of herself to the organisers and she was offered the job. 2001 was to be an important year for Michaela as she received a telephone call from World Snooker asking if she would attend a meeting with a view to joining the snooker circuit as a referee. The following year Michaela made her debut as a snooker referee in a world ranking event when she took charge of the Welsh Open first round match between Ken Doherty and James Wattana. In 1993 she made history by becoming the first ‘Lady Ref’ to officiate at The Crucible during the World Snooker Championships taking charge of Mark King and Drew Henry. Having established herself as a referee on the snooker circuit Michaela in February 2007 became the first lady to referee the final of a world ranking event when she officiated at the final of the Welsh Open between Neil Robertson and Andrew Higginson. This was followed by refereeing the 2008 finals of the Masters at the Wembley Conference Centre and also the final of the China Open in Beijing. Having refereed a number of ranking event finals the supreme honour in snooker refereeing was given to Michaela in 2009 when she officiated at the final of the World Championship at The Crucible between John Higgins and Shaun Murphy. Michaela still continues to referee at Pool and is a regular in The Philippines and Las Vegas, much to her fans delight. Away from the sport Michaela, who rejoices in the soubriquets of "Lady Ref" and "The Queen of Snooker" resides in Dunfermline with her two sons Morgan and Preston and her husband Ross. When not refereeing Michaela enjoys reading, poker, facebook and twitter! STBS - Have you ever visited any of the clubs in the St Blazey & District Snooker League (Cornwall) before? MT - I have yes, had a lovely night at the Lostwithiel Conservative club, I have also been to the Club in Falmouth (Bells Court) which i think is shutdown now that was for Paul Williams. I have also been to the Keay Theatre for Snooker plus a couple of times over the years. STBS - Do you play any snooker or pool? MT - Maybe once in a while on social occasions I will have a game of pool but never go near a snooker table, I used to play pool for Scotland as you will pick up from in the bio, but nowadays having a family and travelling a lot the last thing I want to do is go out and play. A few of the other refs do play a bit I know Jan Verhas plays a little. STBS - Have you always wanted to be a snooker/pool referee? MT - To be honest I just stumbled into it, when I used to play pool for Scotland I met my husband who was a professional pool player, one of the events that he was asked to play in an american 9 pool televised event which was a 1 day event held in scotland, he knew that from playing previously that they didn''t have a referee in Scotland infact they used to have to pay to have someone shipped up from England, he saw an opportunity and put my name forward, so the organisers asked me to submit my CV to them. I actually made up the CV as I had never refereed 9 ball before, but they loved the CV and I got the job. I then went on the internet and got the rules for 9 ball learned them and went on to referee the matches for them, that was Matchroom and I have worked with them ever since. This all happened in 1997 so I have being doing it for 15 years now. STBS - How much fun is it to referee Snooker Legends, and are there any players you have never got the chance to meet/referee that you wish you had? MT - Well for me what''s been amazing about the legends is that i have ticked a lot of boxes for players that I have never managed to ref on the normal snooker circuit. The ones that are really left unturned are the older players, you know the ones that don''t play anymore and the ones that sadly are no longer with us. I mean I even managed Joe Johnson professionally at one point:-) So yeah your Bill Werbeniuk the players I will never have an opportunity to meet or referee, it''s a shame as when I was growing up and watching snooker these were the guys that were on the table at the time. I have been lucky enough to ref Alex Higgins, and I have been lucky enough to ref Ray Reardon as well of course this during legend matches. STBS - Who is your favourite TV commentator? MT - Hard choice, I have always loved John Virgo, Im not biased in that respect but he has always talked the right stuff over the years, I have to say now now Neal Foulds is amazing and one of my other favourites has to be Stephen Hendry purely because he was such a great player and he talks about the game from a players perspective all very natural and lovely to listen too. STBS - Who is your favourite professional player and why? MT - Can''t really pick as I''m friends with so many of them and it would be unfair to single one out. STBS -Do you think the players give the referees the respect they deserve? MT - Actually no I don''t not at all i feel that on the whole that they don''t even appreciate the job that we are doing. You know you can be out there sometimes for hours and hours on your feet and they have got no form of respect for what that is doing to you mentally and physically, to be a good ref you have got to stay with the game and the concentration that you have to put in sometimes in these matches is quite frankly immense. I know that there are some players that really don''t think you need to do much to be a ref, but you know they should go out and try it themselves. STBS - If you could change one rule in snooker, which one would it be? MT - At the moment I have a massive problem with the push shot rule as it''s not being enforced correctly at all and it hasn''t for a while, i think whats happened is over a period of time players have been given a little bit more and a little bit more and they have been allowed to hit the ball a bit thicker and now it''s not being called by the refs to the point where in my opinion push shots are being played pretty regularly. So it''s such a grey area now you almost leave it up to the player and you shouldn''t really have to do that. I suppose its just the way this has developed over a period of time but I think this needs addressing. STBS - Has there ever been a scenario where you didn''t know the rule? MT - I can''t think of one that jumps out in snooker but there has been in pool, because I hadn''t been taught the rules of 9 ball I as trying to learn them from the internet which wasn''t very easy, I had a situation with the lag where the players ball went in off and I didn''t know the rule, it''s at that moment when you go into freeze and think oh my god what do I do. STBS - What is the hardest part of refereeing? MT - Concentration and focus over long period of time, i mean everyone gets tired but as we now it''s difficult to do your job when your tired, like with playing refereeing is a mind thing STBS - Do you have a favourite venue? MT - I actually have 2, the first is the crucible theatre in sheffield because it''s so small and intense, you can hear everything in there even people whispering, and the other is the Temperdrome in Berlin, its very similar because it''s round like the crucible and it can fit 2500 people in it as opposed to 1000 like the crucible, the noise and atmosphere that is created is amazing, the german masters is there now and especially with the setup of the tables it''s amazing, everyone can watch all matches that are being played. STBS - What has been the most memorable snooker match your have refereed or seen? MT - I''m going to give you a few answers here, one I have refereed and one that I have not and one I have marked as well. The first in 1982 Alex Higgins world championship win was probably actually the first time I actually cried at a snooker match that is as a viewer of the television. And the other has to be the John Higgins v Ronnie O''Sullivan masters final in 2006 I was the marker in the this match John came back and beat Ronnie in the final frame I think Ronnie was 58 ahead with 59 on the table or 60 ahead with 59 on the table something like that, Ronnie had thought he had won it but John as he always does dug deep and managed to clear up and pinch it including doubling the final red, he wins the title by 1 point in the final frame, i was scoring the match and I just couldn''t breath it was so intense. I did the shanghai masters final as well this year which was unbelievable again John Higgins loosing 7-2 in the first session but making a 147 everyone had written him off but I knew that it could be long evening you should never write John Higgins off, how he does it god knows and the bottle he has unbelievable. A little thing I do for my pre match preparation is to have a can of red bull (sugar free most times) but on this particular occasion I have taken 2 cans because I just thought you might want another one of them in the interval sure enough it went 7-6, so I downed the second can and went out to see out the match. A phenomenal final:-) STBS - Funniest moment for you so far in your career? MT - Well that wouldn''t be too difficult would it, when I picked up the cue ball when reefing Stephen MGuire and Graham Dott in the World Champs i think everyone''s seen it now and it''s turned out to be a classic moment:-) although it wasn''t that funny at the time it happened, anyone that ever comes up to me or knows me always mentions it I suppose it will never go away. STBS - Do you have any ambitions as a referee you still have not achieved? MT - None really, to be honest with you no, I have really been lucky in what I have managed to achieve you know I have not done the UK final and there are obviously other finals I haven''t done but i''m not one of those refs you wants or needs to tick all those boxes, I''m delighted with what I have achieved, we have a while legion of female refs coming through now because I have led the way, and you now what I think yeah you have done good girl and i''m really happy with that. Question Time Date of birth: 11th December 1967 Star sign: Sagittarius Favourite Colour: Yellow Favourite food: Italian - I''m a pizza and pasta freak! Favourite drink: Coffee or Rose wine depends on the occasion;-) Favourite subject at school: Biology Favourite UK destination: Cornwall everytime Favourite authors: Peter James, James Patterson and currently Simon Kernick Favorite movie: Shawshank Redemption (My son is named after Morgan Freeman) Favourite TV programme: House and usual Strictly, X-Factor and their American versions, we SKY+ them all! Favourite music: All sorts, too many to mention Favourite snooker venue: The Crucible for the intimacy and The Tempodrom in Berlin for the noise! Favourite pool venue: Anywhere in the Philippines and York Hall for the Mosconi Cup Worst habit: Being late and doing everything at the last minute... Dislikes: Violence of any kind, especially to kids and animals grrrrrrrrrrr Tell us two things we don''t know about you: Firstly, I am a games freak - I have been a Super Mario fan for over 20 years and a Zelda fan since its launch. Secondly, I used to work as a successful sales rep for Ann Summers!!! Images Courtesy of: Action Images Bio and small facts courtesy of the Michaela Tabb Website:', '2014-01-01', false, 'Richard Pearson'),
  ('CUEVIEW - Mike Dunn', 'cueview-mike-dunn', 'Cue View', '[]'::jsonb, 'Mike Dunn, kindly agreed to speak to us this week and continue our professional CueView feature.', null, '"As he was waving and shouting at me he forgot to look forward and crashed into the back of a parked car !!!He picked himself up and walked towards me like a scene from a Horror movie just to get my autograph."', 'Mike Dunn, kindly agreed to speak to us this week and continue our professional CueView feature.

more For those of you who are not familiar with Mike''s name then Mike is a professional snooker player from the North East of England''s, he has twice reached the last 16 of a ranking event. You will have seen him on TV a few times, and he gave Matthew Stephens a good run for is money at the crucible recently. Mike loves a good joke and is an avid twitter user. Enjoy STBS - What is your full name please MD - Andrew Michael Dunn STBS - Your Current Club/base MD - Hartlepool snooker centre STBS - Your Highest Break (if 147 how many) MD - 147 German masters 2012 (lost count in practice) STBS - Are you Left/Right Handed or both MD - I''m right handed. STBS - Bio about yourself (in no more than 200 words) MD - I''ve been a pro for 22 years (use the info from world snooker.com because I don''t know where to start) STBS - What was your first ever memory of snooker? MD - Alex Higgins playing on Tv in the 70''s STBS - At what age did you start playing snooker and why? MD - 8yrs old playing customers waiting for a hair cut in my dad''s barber shop STBS - What has been your greatest achievement in snooker? MD - Got to say playing at the crucible many players have not played there in their career STBS - Who is the most famous professional player you have played or met? (can be modern or older era) MD - played and sat over a cup of tea with Fred Davis STBS - Who is your favourite TV commentator? MD - None because sooner or later one talks rubbish and upsets me STBS - What is your Favourite professional player and why? MD - Love Jimmy White even to this day STBS - What has been the most memorable snooker match you have ever seen? MD - 1985 world final STBS - Do you have any snooker ambitions you still have not achieved? MD - Not really although I would like to play at the crucible again. STBS - Who is your bogey player? MD - Played Jimmy White 3 or 4 times and just don''t perform against him. STBS - Funniest moment in your snooker experience? MD - Shortly after beating James Wattana at his prime live on tv in Thailand I was walking round Bangkok with my dad I was stopped by a thai snooker fan who shouted for my autograph whilst on a motor bike, As he was waving and shouting at me he forgot to look forward and crashed into the back of a parked car!!!He picked himself up and walked towards me like a scene from a Horror movie just to get my autograph. STBS - Who is the most under-rated player in professional snooker? MD - Ding is incredible in practice I played him once he beat me 8-0 and had 2 147''s and five century''s Thanks Mike, It''s been great chatting with you and we wish you all the best for the rest of the reason, hey maybe you might draw Jimmy and finally beat him this year. Images Courtesy of: Mike Dunn - (yes his own images)', '2014-01-01', false, 'Richard Pearson'),
  ('CUEVIEW - Paul Baron', 'cueview-paul-baron', 'Cue View', '[]'::jsonb, 'This edition of CUEVIEW features Mr Paul Barron from Tywardreath', null, '"Watching Darren Kirwan riding around RBL in a wheelchair - funny as!"', 'This edition of CUEVIEW features Mr Paul Barron from Tywardreath

more STBS - What is your full name please PB - Paul Baron STBS - Your Current Club/base GL - Tywardreath A STBS - Your Highest Break PB - 99 STBS - Are you Left/Right Handed or both PB - I''m right handed. STBS - Bio about yourself (in no more than 200 words) PB - Delivery driver, outgoing love any sport especially golf STBS - What was your first ever memory of snooker? PB - Watching Alex Higgins win the Worlds in 1982 STBS - At what age did you start playing snooker and why? PB - 30 fed up with pool STBS - What has been your greatest achievement in snooker? PB - Winning doubles with Ian Hewitt, anyone who can win with him is an achievement STBS - Who is the most famous professional player you have played or met? (can be modern or older era) PB - Jimmy White STBS - Who is your favourite TV commentator? PB - John Virgo STBS - What is your Favourite professional player and why? PB - Ronnie O''Sullivan no equal STBS - What has been the most memorable snooker match you have ever seen? PB - Ronnie O''Sullivan v Stephen Hendry UK Champ final STBS - Who is the best player in the league? PB - Andrew Best STBS -Who is the most under-rated player in the league? PB - Sorry can''t choose STBS - Funniest moment in your snooker experience? PB - Watching Darren Kirwan riding around RBL in a wheelchair - funny as! STBS - Who is your bogey player? PB - Aint got one, no-one good enough!! haha STBS - Do you have any snooker ambitions you still have not achieved? PB - To win the leaue with current RBL squad Cheers Paul Images Courtesy of: Richard Pearson', '2014-01-01', false, 'Richard Pearson'),
  ('CUEVIEW - Peter Williams', 'cueview-peter-williams', 'Cue View', '[]'::jsonb, 'Did you know that it is possible to play over seventy different games on a snooker/pool table?', null, '"Earlier this year, I created "Pete''s AMAZING Chalkless Super-Grip Cue Tips1 copyright 2012" and at precisely 10.08am on Sunday the 30th September during the 1st round of the World Seniors Snooker Championships 2012 against Nigel Bond in Sheffield, I became the ''first ever person'' to pocket a ball using a ''chalkless cue tip'' at a WPBSA sanctioned Professional Snooker Tournament."', 'Did you know that it is possible to play over seventy different games on a snooker/pool table?

more Well it is and Peter Williams is the creator of many an amazing Cue Sport Game. In our latest CueView Peter explains about his passions for snooker and a little bit about his unique Cue games and exhibitions.For more details please follow this link to his website STBS - What is your full name please PW - Peter Williams STBS - Your Current Club/base PW - Table at home STBS - Your Highest Break PW - Very rarely play any snooker on a full-size table these days. 145 - Not compiled a 147 but have managed a 155 during an Exhibition up in Scotland when I actually had no intention to include snooker as one of the games to be played that particular night. (as explained during my Exhibitions STBS - Are you Left/Right Handed or both PW - Left (but get by Right also) STBS - Bio about yourself (in no more than 200 words) PW - Been a member of the WPBSA since 1990 but since the back end of the 1980''s, have been performing my unique exhibitions of a compendium of what is now OVER 70 DIFFERENT GAMES which can be played on a snooker and pool table. Am also the creator, manufacturer and sole worldwide distributor of “Pete’s AMAZING Chalkless Super-Grip Cue Tips1 ©2012” and YES, THEY DO WORK! STBS - What was your first ever memory of snooker? PW - When I was about 10 years old. my grandparents took me to see an Exhibition by Ray Reardon at ''Y Ganolfan'' (a community centre) in Porthmadog here in N Wales. I still have the programme for that evening and oddly enough, it''s number is actually 147! STBS - At what age did you start playing snooker and why? PW - About 10 - I ''blame'' Ray Reardon STBS - What has been your greatest achievement in snooker? PW - Earlier this year, I created "Pete''s AMAZING Chalkless Super-Grip Cue Tips1 copyright 2012" and at precisely 10.08am on Sunday the 30th September during the 1st round of the World Seniors Snooker Championships 2012 against Nigel Bond in Sheffield, I became the ''first ever person'' to pocket a ball using a ''chalkless cue tip'' at a WPBSA sanctioned Professional Snooker Tournament. STBS - Who is the most famous professional player you have played or met? (can be modern or older era) PW - During the 1980 and 1990''s have been honoured to promote Snooker Exhibitions for Ray Reardon and many other top professional snooker and billiards players of that period (as mentioned in my website: www.cuegamesexhibitions.co.uk) Learned a great deal from all those memorable experiences. STBS - Who is your favourite TV commentator? PW - There aren''t any poor snooker commentators, isn''t there. But it''s a great shame that the likes of the late Jack Karnehm and the ''Whispering) Ted Lowe are no longer with us STBS - What is your Favourite professional player and why? PW - I don''t have a ''Favourite'' professional player as such, but, I''ve yet to see a professional snooker player who can play right and left-handed as good as Ronnie O''Sullivan can. STBS - What has been the most memorable snooker match you have ever seen? PW - Probably not the most nail-biting of matches ever, but, it was great to see Cliff Wilson defeating Eddie Charlton 5-4 to win the 1991 World Seniors Snooker Championship STBS -Who is the most under-rated player in professional snooker? PW - Despite having lost all of his six World Championships finals - But, ''how'' can Jimmy White be classified as an ''under-rated'' player? In my humble opinion, "What''s meant to be, shall be!" And at the end of the day, "Does it really matter who wins or loses?" STBS - Funniest moment in your snooker experience? PW - During a Ffestiniog & District League Youth Shield tournament in Porthadog many moons ago, I was a refereeing a match and one of the players was young and short he needed to use the rest to break off! Towards the end of the only frame they played, there became a shot where he simply couldn''t reach the last but one red with the rest equipment which were available at the club. Therefore, I decided to move the cue ball forward about three feet, and to my horror, he calmly went on to pot another red which wasn''t pottable before and as a result, went on to win his match! STBS - Who is your bogey player? PW - I have no ''bogey player'' simply because I believe that one''s opponent can only as good as you allow him/her to be. In other words, as long as you occupy the table, your opponent CANNOT POT A SINGLE BALL! STBS - Do you have any snooker ambitions you still have not achieved? PW - Hope to be able to continue performing my Cue Games Exhibitions for as long as I can Images Courtesy of: Peter Williams', '2014-01-01', false, 'Richard Pearson'),
  ('CUEVIEW - Ray Edmonds Exclusive', 'cueview-ray-edmonds-exclusive', 'Cue View', '[]'::jsonb, 'A blast from the past today, I''m sure a lot of you will remember Ray Edmonds, as a player and more recently as a TV commentator.', null, '"Probably the time when Alex Higgins came before the WPBSA board accused of peeing in a plant pot back stage at the Crucible theatre . His explanation was hilarious, made more so as he had arranged for champagne and orange juice to be delivered to the board meeting before he appeared."', 'A blast from the past today, I''m sure a lot of you will remember Ray Edmonds, as a player and more recently as a TV commentator.

more Ray has many memories to tell and has kindly started the ball rolling with a CueView for us. There is more to come soon with some additional memories from the Jonathan Barron years - we can''t wait. STBS - What is your full name please RE - Ernest Raymond Edmonds (known as Ray) STBS - Your Current Club/base RE - I now live in Spain but obviously my club is still the Ray Edmonds Snooker Centre opened in 1983 STBS - Your Highest Break RE - 143 in a match at Romford against Cliff Wilson STBS - Are you Left/Right Handed or both RE - Right handed STBS - Bio about yourself (in no more than 200 words) RE - What can I say. Played in the Grimsby league from 1954 onwards for many years. Made the 1st ever Hundred at snooker in the league in 1958. Entered the English chship in 1961 for the 1st time, losing in the final at Burroughes Hall to Alan Barnett. Remained an amateur until 1979 and perhaps should have done it earlier but had a wife and family and was enjoying life. Had 3 wonderful trips to South Africa and Rhodesia in the mid 70s, not happy with the politics but the hospitality and the country was amazing. Started commentary for the BBC in 1981 before moving to ITV later that year. Had 7 very good years with ITV and went back to BBC in 1988 for the next 12 years or so. Absolutely loved it and not at all happy when they “retired” me. Have very old fashioned views on TV sports commentary. Far too much talking nowadays and I like the old adage which is let the pictures tell the story and don’t interfere with viewers enjoyment but I am afraid it will not happen. Snooker as with many other sports is very much overproduced and seems to find the lowest common denominator. That is my Victor Meldrum moment over!!! I must still say that snooker and billiards gave me a great life and I don’t regret a minute. STBS - What was your first ever memory of snooker? RE - First memory is playing on a 6ft table top in a friends house. He preferred football so I got to use the table most of the time. STBS - At what age did you start playing snooker and why? RE - About 7/8 years on the small table, 11 On a fullsize. STBS - What has been your greatest achievement in snooker? RE - Maybe 2 successive World Amateur Snooker titles, 2 successive CIU titles or could be World Pro Billiards champion in 1985. Still the only player to have won World Amateur Snooker and a World Pro Billiards. STBS - Who is the most famous professional player you have played or met? (can be modern or older era) RE - So many. The legend Joe Davis I met 2 or 3 times but never saw him play live. Modern, take your choice, I have met and lost to all of them, and beaten the odd one!!!! STBS - Who is your favourite TV commentator? RE - Not a fair question as I obviously thought I was the best!!! All of the present lot are good and know the game but all talk a lot more than necessary. I do like listening to Stephen Hendry, his observations are good but I hope he doesn’t become too verbose. STBS - What is your Favourite professional player and why? RE - Very difficult- Ronnie perhaps the most fluent player ever but I would pick Stephen Hendry, purely for the fact that h e was relentlessly good and has set records that will stand for a very long time. Apart from that I found him to be very modest off the table but so single-minded about his snooker in competition. STBS - What has been the most memorable snooker match you have ever seen? RE - Most memorable match so difficult again to choose. My own perhaps was losing to Alex Higgins 9-8 in the UK chship. The obvious one is Davis- Taylor 1985. Massive audience and interest that will I doubt ever be seen again. STBS -Who is the most under-rated player in professional snooker? RE - Most underrated player nowadays I really would not know. In my prime perhaps Dennis Taylor before he won the World title. We knew he was good but most of his fellow pros would not have predicted his success. He obviously proved us wrong over the period 1984/87. STBS - Funniest moment in your snooker experience? RE - Probably the time when Alex Higgins came before the WPBSA board accused of peeing in a plant pot back stage at the Crucible theatre. His explanation was hilarious, made more so as he had arranged for champagne and orange juice to be delivered to the board meeting before he appeared. STBS - Who is your bogey player? RE - My bogey player was John Spencer whom I never beat as an amateur or a pro over a period of over 20 year until I finally beat him in 1988, the one and only time. I have to say that I thought he was the snooker players “professional” and I admired him very much and was a very good friend and it was a great loss when he died. STBS - Do you have any snooker ambitions you still have not achieved? RE - Any snooker ambitions I had have long since gone- I have not played at all for over 3 years. Images Courtesy of: Dave Muscroft', '2014-01-01', false, 'Richard Pearson'),
  ('CUEVIEW - Richard Pearson', 'cueview-richard-pearson', 'Cue View', '[]'::jsonb, 'This edition of CUEVIEW features Mr Richard Pearson of Tregonissey snooker club', null, '"This is a hard one as there are so many, loads of Masters finals have been amazing, but I would probably go for the Belgium Open in 2011 Judd v Ronnie, Judd won 4-3 and was 3-0 up but Ronnie came back with 2 tons to level the match was over in less than 90 mins."', 'This edition of CUEVIEW features Mr Richard Pearson of Tregonissey snooker club

more STBS - What is your full name please RP - Richard Pearson (richyp147) STBS - Your Current Club/base RP - Tregonissey A STBS - Your Highest Break RP - 118 STBS - Are you Left/Right Handed or both RP - I''m left handed. STBS - Bio about yourself (in no more than 200 words) RP - All rounder really, I love playing snooker, i''m a graphic designer and web designer by trade, I take photos and design things, I''m a family man through and through. STBS - What was your first ever memory of snooker? RP - Watching the 1985 black ball final between Steve Davis and Dennis Taylor, I was 13 and allowed to stay past midnight to watch Dennis Taylor and that famous cue in the air... STBS - At what age did you start playing snooker and why? RP - 11 at a club in Somerset, Saturday mornings were boring so started to play STBS - What has been your greatest achievement in snooker? RP - Most probably winning every league I have played in Cornwall in, Penwith, Perranporth, Mining League, Newquay, and St Blazey STBS - Who is the most famous professional player you have played or met? (can be modern or older era) RP - I have been lucky enough to meet and play loads, Ronnie O''Sullivan, John Parrott, Stephen Hendry, Ken Doherty, Paul Hunter, Matthew Stephens, Jimmy White to name but a few (the perks of working for a newspaper all those years ago) STBS - Who is your favourite TV commentator? RP - Ken Doherty & Dennis Taylor, Willie Thorne annoys the hell out of me, never gets anything right and talks non stop STBS - What is your Favourite professional player and why? RP - As a kid I always followed Jimmy White, but these days it''s Ronnie O''Sullivan and Judd Trump STBS - What has been the most memorable snooker match you have ever seen? RP - This is a hard one as there are so many, loads of Masters finals (JW''s bend shots in the semi of the masters v Kirk Stephens) have been amazing, but I would probably go for the Belgium Open in 2011 Judd v Ronnie, Judd won 4-3 and was 3-0 up but Ronnie came back with 2 tons to level the match was over in less than 90 mins, a feast of ridiculous potting. STBS - Who is the best player in the league? RP - Now Barrie for sure, but back then Jonathan Barron STBS -Who is the most under-rated player in the league? RP - Tricky one, Paul Barron is always hard to beat and I always struggle against Leyton STBS - Funniest moment in your snooker experience? RP - I have loads and loads to tell, but one always sticks in my mind, when playing for Pendeen in the Penwith league 2 incidences happened in one evening, firstly the table was being ironed and the light went out, the money was put in the meter, the iron picked up and the person carried on ironing the table, what he didn''t know was that when he put the iron on the floor the floor didn''t have carpet and was full of muck, he burn''t a hole in the cloth and ruined it with a giant streak down the table. On the same eve a player in our opponents team wasn''t happy he had lost and decided to storm out of the club snapping his cue over his knee in the process, he then threw it down the road and drove off - very funny evening STBS - Who is your bogey player? RP - Don''t really have one, have struggled to beat the extremely lucky David Grose of late STBS - Do you have any snooker ambitions you still have not achieved? RP - Not really maybe to beat my high break of 118, or to win the County if I can be bothered to enter Cheers Richard some nice detail in your responses there Images Courtesy of: Richard Pearson', '2014-01-01', false, 'Richard Pearson'),
  ('CUEVIEW - Ryan Bilson', 'cueview-ryan-bilson', 'Cue View', '[]'::jsonb, 'THIS EDITION OF CUEVIEW FEATURES MR RYAN BILSON', null, '"Mark Williams winning world champs 2000 against Matthew Stephens"', 'THIS EDITION OF CUEVIEW FEATURES MR RYAN BILSON

more STBS - What is your full name please RB - Ryan Bilson STBS - Your Current Club/base RB- Tregonissey A STBS - Your Highest Break RB - 112 STBS - Are you Left/Right Handed or both RB - I''m right handed. STBS - Bio about yourself (in no more than 200 words) RB - Outgoing, friendly likes to have a laugh and supports Liverpool STBS - What was your first ever memory of snooker? RB - Mark Williams winning world champs 2000 against Matthew Stephens STBS - At what age did you start playing snooker and why? RB - 17 all because I had a bad injury playing football so started a new sport STBS - What has been your greatest achievement in snooker? RB - Beating Darren Lock when 63-0 down and won 65-63 great comeback STBS - Who is the most famous professional player you have played or met? (can be modern or older era) RB - Ronnie O''Sullivan STBS - Who is your favourite TV commentator? RB - Dennis Taylor STBS - What is your Favourite professional player and why? RB - Judd Trump great attacking player STBS - What has been the most memorable snooker match you have ever seen? RB - John Higgins 18-15 Judd Trump World Final 2011 STBS - Who is the best player in the league? RB - Barrie McIntosh STBS -Who is the most under-rated player in the league? RB - Steve Courts STBS - Funniest moment in your snooker experience? RB - Henry McGall picking up the white thinking it went in off - cost him the match STBS - Who is your bogey player? RB - Richard Broad STBS - Do you have any snooker ambitions you still have not achieved? RB - St Blazey singles winner Thanks Ryan Images Courtesy of: Richard Pearson', '2014-01-01', false, 'Richard Pearson'),
  ('CUEVIEW - Sean ''The Storm'' O''Sullivan', 'cueview-sean-the-storm-osullivan', 'Cue View', '[]'::jsonb, 'The latest edition of CUEVIEW features a new young 18 year old professional called Sean O''Sullivan, Sean has only just gained his professional card for the main tour and is already showing great promise, we were…', null, '"I think without doubt it''s turning professional. Not many people believed I was good enough to qualify but I knew I was good enough and had it in me to do it, but to do it as early as I have is an added bonus!"', 'The latest edition of CUEVIEW features a new young 18 year old professional called Sean O''Sullivan, Sean has only just gained his professional card for the main tour and is already showing great promise, we were delighted that he took the time to talk with us.

more Watch this space as you saw it first on St Blazey Snooker we are sure Sean is going to make a huge impact in coming seasons. STBS - What is your full name please SO - My full name is Sean Francis O''Sullivan STBS - Your Current Club/base SO - Upton Park Snooker Centre STBS - Your Highest Break (if 147 how many) SO - My highest break is 142. STBS - Are you Left/Right Handed or both SO - Just right handed, can''t play left handed to save my life! And as I''m not the tallest person in the world I don''t mind using the rest! STBS - Bio about yourself (in no more than 200 words) SO - Well I''m a hard working 18 year old just trying to follow my dream, and I''m living my dream being a professional snooker player. Away from the table I''m a massive arsenal fan and love all sports in general. STBS - What was your first ever memory of snooker? SO - I remember always watching big break when I was young and any time the snooker was on tv I''d be glued to the television screen. I think I vaguely remember ken winning the worlds back in ''97 as all my family are irish so everyone was going mad haha! STBS - At what age did you start playing snooker and why? SO - When I was about 9 years old. I''ve always played pool since I was young in a pub my mum and dad worked in, and after I began playing for London under 18s at the age of 8 my dad thought it would be a good idea to have a go at snooker! STBS - What has been your greatest achievement in snooker? SO - I think without doubt it''s turning professional. Not many people believed I was good enough to qualify but I knew I was good enough and had it in me to do it, but to do it as early as I have is an added bonus! STBS - Who is the most famous professional player you have played or met? (can be modern or older era) SO - Well I''ve played them all near enough of the modern era. But one for some of the older snooker fans would be Patsy Fagan. I played him in a pro am once when I was about 12 and he is one of the nicest people you could ever wish to meet. Also meeting Alex Higgins at an exhibition he was doing with Jimmy White was a great experience. STBS - Who is your favourite TV commentator? SO - Stephen Hendry without a doubt. There''s a reason he is the greatest of all time as a player and that''s helped him with the commentary as well. His knowledge and being able to explain what is going on to the viewer, especially those who don''t play is amazing. He has seen it all and there is no one better. STBS - What is your Favourite professional player and why? SO - Not really difficult this one, Ronnie has been my idol since I began playing the game and you can learn so much from watching him play. His break building is faultless most of the time and that''s why he brings the crowds in. STBS - What has been the most memorable snooker match you have ever seen? SO - Hmm, good question. There have been some unbelievable matches. Watching on the tv, the one I will never forget is the match between Ronnie and Paul Hunter in the final of the Masters. That match had absolutely everything, with such drama at the end as well. The match I''ll never forget when actually being at the venue, would be Ronnie against Mark Williams in 2008 at the world championships, a great moment being able to see Ronnie make that 147 to win the match. What an amazing break! STBS - Do you have any snooker ambitions you still have not achieved? SO - Most definitely. Moving up the rankings is the first, getting to a venue would be another great achievement. Then after that, the sky is the limit! STBS - Who is your bogey player? SO - Well since I''ve got on the tour there''s only one person I''ve played twice, Ian Burns, and haven''t beaten him on either occasion, so that''s as close as I can come to a bogey player I suppose! STBS - Funniest moment in your snooker experience? SO - Well quite a random one I can think of is once someone in my club was playing a match against one of his mates. He went to the toilet and during that time his other mate cut his tip off and replaced it with a bit of blu tac. He came back to break off in the next frame, and luckily didn''t check or chalk his cue, so he broke off, and what happened after that was utterly hilarious. The look of confusion and shock when what he thought was his tip stuck to the white ball was a picture! STBS - Who is the most under-rated player in professional snooker? SO - I''m not sure about under-rated, but certainly from the players new to the tour who I really think has potential for great things, would be Scott Donaldson from Scotland. He''s a good mate of mine as well. Having played him before, I know how good he is and how great he could be! But the standard is so good these days it''s so difficult to make it to the top, so you just never know what could happen or who could break through, hopefully I''ll be up there at the top one day! Thank you Sean for taking the time to speak to us, good luck for the rest of the season, we will be watching you with anticipation. Images Courtesy of: Monique Limbos', '2014-01-01', false, 'Richard Pearson'),
  ('CUEVIEW - Sean Storey Exclusive', 'cueview-sean-storey-exclusive', 'Cue View', '[]'::jsonb, 'Whilst tracing my steps in researching Jonathan Barron I stumbled upon a lot of great links to Grimbsy snooker it''s professionals and the hotbed of talent that especially came out of Ray Edmonds snooker club. On this…', null, 'Last 16 of the worlds, what a great venue the Crucible and the World Championships in general and also making 2 maximum breaks in one day in a pro-am which I got in the Guinness Book Of Records for."', 'Whilst tracing my steps in researching Jonathan Barron I stumbled upon a lot of great links to Grimbsy snooker it''s professionals and the hotbed of talent that especially came out of Ray Edmonds snooker club. On this note I tracked down ex snooker professional Sean Storey for a detailed chat.

more Sean was (and most probably still is) a hugely talented player but sadly retired from the game a few years back now, however Sean phoned me today to answer some questions and it was then I realised what a fantastic guy Sean is, Sean spent the best part of an hour on the phone to me talking snooker, life and Grimsby - read on and enjoy his CueView STBS - What is your full name please SS - Sean Storey STBS - Your Highest Break SS - 147 x well over 100 (including 3 in one day in practise and 2 in one day in a pro am that is in the guiness book of records) On one practice session over 40 frames I had 17 tons and 3 maximums - very proud of that:-) STBS - Are you Left/Right Handed or both SS - I''m right handed STBS - Bio about yourself (in no more than 200 words) SS - Born August 19th 1971. My best ranking tournament performance came in the World Championship in 2003, where I lost in the last 16 to John Higgins 13-7. Previously in qualifying I had beaten Mike Dunn, Michael Holt and Dominic Dale. I had also qualified for the Crucible in 2001 beating Stephen Maguire 10-4 and Terry Murphy in the final qualifier 10-9 before losing to Joe Swail at the Crucible 10-9 after being 9-7 up. My best season was 2002/03 when I won 28 matches overall - the most out of anyone on the tour. I got to the semi finals of the B&H qualifier in Mansfield losing to the eventual winner Ryan Day. My best ranking tournament break was 145 in the 2001 British Open. STBS - What was your first ever memory of snooker? SS - Watching it on TV. STBS - At what age did you start playing snooker and why? SS - Can''t remember why but I was about 14 STBS - What has been your greatest achievement in snooker? SS - Last 16 of the worlds, what a great venue the Crucible and the World Championships in general and also making 2 maximum breaks in one day in a pro-am which I got in the Guinness Book Of Records for. STBS - Who is the most famous professional player you have played or met? (can be modern or older era) SS - Not sure met virtually all of them STBS - Who is your favourite TV commentator? SS - I have to say Ray Edmonds as I played in his club during my career and he helped me a lot, to be fair he is a very good commentator. STBS - What has been the most memorable snooker match you have ever seen? SS - Probably 1985 world final STBS -Who is the most under-rated player in professional snooker? SS - Me:) STBS - Funniest moment in your snooker experience? SS - Too many to mention, I had a great time and alot of fun during my career, probably too much. STBS - Who is your bogey player? SS - Steve Davis, played him 3 times and lost 3 times STBS - What is your favourite Professional and why? SS - I have lots of favorites as they are friends, but unfair to pick one Images Courtesy of: Action Images', '2014-01-01', false, 'Richard Pearson'),
  ('CUEVIEW - Shaun Murphy Exclusive', 'cueview-shaun-murphy-exclusive', 'Cue View', '[]'::jsonb, 'We were lucky enough to catch up with Shaun Murphy last week as he agreed spend a some time away from his busy schedule to do an exclusive CueView interview with us.', null, '"For me the most memorable game i''ve seen was the final of the B & H Masters when Paul Hunter came from way behind to beat Fergal O''brien. I was there live and the atmosphere was unreal."', 'We were lucky enough to catch up with Shaun Murphy last week as he agreed spend a some time away from his busy schedule to do an exclusive CueView interview with us.

more At the time of this interview Shaun is busy preparing to go to China for the new International Open, so it was extra good of him to make the time to speak with us and answer our questions. STBS - What is your full name please SM - My full name is Shaun Peter Murphy STBS - Your Current Club/base SM - Currently moving clubs. I''ve played at Sale cons for 4 years now but will soon start playing at Urmston cons. It''s a very similar club just a little bigger and with a few more tables. STBS - Your Highest Break (if 147 how many) SM - My highest break is 147. I''ve had two in tournament play but none on tv, so thats definitely something i''d like to change in the future. STBS - Are you Left/Right Handed or both SM - I''m right handed but can play a little left handed too. My highest break left handed is 136 but that was a few years ago. I don''t really like to do it in a match as i quite like using the rest. STBS - Bio about yourself (in no more than 200 words) SM - A bit about myself, I''m now 30 and don''t know where my 20''s went. i''m pleased with what i''ve achieved in snooker so far but would like to add some more titles before hanging my cue up in 15 or so years ( maybe ) Away from snooker i play and watch a lot of golf and currently play off a 5 handicap. I''m really into music and play the piano a little bit but not much. STBS - What was your first ever memory of snooker? SM - My first snooker memory is of a table in a hotel in Blackpool we stayed in when i was about 7. I wasn''t allowed in the snooker room but wanted to watch the game my Dad and brother were playing so i snuck in. But every time the manager looked in i had to hide under the table! STBS - At what age did you start playing snooker and why? SM - I started playing by fluke aged 8 at christmas. I''d asked for a commodore 64 computer for christmas but my parents un able to afford one bought me a little snooker table from toys r us and that was it, i was hooked. STBS - What has been your greatest achievement in snooker? SM - Obviously winning the world championship in ''05 is top of my list but winning the uk in ''08 to prove i wasn''t a one trick pony was very important too. STBS - Who is the most famous professional player you have played or met? (can be modern or older era) SM - I remember meeting John Spencer straight after winning the World title. He was the first person to knock on my dressing room door to say well done and that always stuck with me. Ray Reardon has helped me a lot too but for me the best and most professional would be Steve Davis. STBS - Who is your favourite TV commentator? SM - I really like it when Steve Davis commentates as i think he brings a more up to date insight of someone who''s seen it all and done it, and still plays so understands modern playing conditions which are completely different to those of the 80''s STBS - What is your Favourite professional player and why? SM - Again it would have to be Steve Davis. I think he''s the best of all time and still gives anyone a run for their money. STBS - What has been the most memorable snooker match you have ever seen? SM - For me the most memorable game i''ve seen was the final of the B & H Masters when Paul Hunter came from way behind to beat Fergal O''brien. I was there live and the atmosphere was unreal. STBS - Do you have any snooker ambitions you still have not achieved? SM - When i started out in snooker i had three goals. World champion, world number 1 and to buy a mercedes. So far i''ve achieved two out of three. Im still chasing the world number 1 bit though. STBS - Who is your bogey player? SM - Bogey players are hard to name these days because we all play each other so often but historically i always had a problem playing matthew couch back in the day. I''m not sure why but he always seemed to get the better of me. STBS - Funniest moment in your snooker experience? SM - I remember a match at the qualifiers in Prestatyn years ago. I''d snookered my opponent ( who i cant name ) and as he bent down to look at the swerve he broke wind so loudly we all had to stop playing for laughter. It was some 10 or 15 mins later when we were able to start again. STBS - Who is the most under-rated player in professional snooker? SM - A really tough question to answer as i think since the introduction of the PTC''s the general standard of snooker on tour has gone through the roof. Thank you Shaun for taking the time to speak to us, good luck next week in China, we will be watching and wish you all the best for the rest of the season and the future. What a gent Images Courtesy of: Action Images & Günter Leitenbauer', '2014-01-01', false, 'Richard Pearson'),
  ('CUEVIEW - Steve Davis Exclusive', 'cueview-steve-davis-exclusive', 'Cue View', '[]'::jsonb, 'Steve was a difficult man to catch up with, although kindly he made time for me at the recent masters to talk Snooker and fill in his CueView - thanks Steve a gent as always...', null, '"Davis'' achievements also include three Masters and a record six UK Championship titles. In 1988 he became the first player to complete snooker''s Triple Crown in a single season. He is also a former four-time World Doubles champion with Tony Meo and won the World Team Classic/World Cup four times with England. In 1982, he became the first player to compile an official televised maximum break and is one of five players to have compiled over 300 competitive century breaks."', 'Steve was a difficult man to catch up with, although kindly he made time for me at the recent masters to talk Snooker and fill in his CueView - thanks Steve a gent as always...

more STBS - What is your full name please SD - Steve Davis STBS - Your Current Club/base SD - No fixed abode as always travelling to matches and doing commentary STBS - Your Highest Break SD - 147 STBS - Are you Left/Right Handed or both SD - One guess:-) STBS - Bio about yourself (in no more than 200 words) SD - Steve Davis, OBE (born 22 August 1957 in Plumstead, London)is an English professional snooker player. He has won more professional titles in the sport than any other player, including six World Championships during the 1980s, when he was the world number one for seven years and became the sport''s first millionaire. He has won 28 ranking events in total, second only to Stephen Hendry. Davis'' achievements also include three Masters and a record six UK Championship titles. In 1988 he became the first player to complete snooker''s Triple Crown in a single season. He is also a former four-time World Doubles champion with Tony Meo and won the World Team Classic/World Cup four times with England. In 1982, he became the first player to compile an official televised maximum break and is one of five players to have compiled over 300 competitive century breaks. Though he has not won a major tournament since 1997, he continues to play snooker at a high level and reached the quarter-finals at the 2010 World Championship. He was still ranked in the world''s top 16 at the age of 50, and is ranked number 47 after the 2012 Munich Open. Davis has also competed in pool and poker events and has written books on a variety of subjects. He played at the Mosconi Cup between 1994 and 2004 as a member of Team Europe, winning the event in 1995 and 2002, and reached the final table of the 2003 Poker Million. He was made an MBE in 1998 and an OBE in 2001. He now combines his playing career with his role as an established television analyst and occasional commentator for the BBC''s snooker coverage. STBS - What was your first ever memory of snooker? SD - Seeing a black ball on a snooker table and walking to the table, reaching up on tip toes and trying to pick it up to shouts to stop STBS - At what age did you start playing snooker and why? SD - 14 ish. Went to A Holiday Camp for a family holiday and did nothing else other than play snooker with my father all week. STBS - What has been your greatest achievement in snooker? SD - Tricky one! Greatest Achievement. Still a Main Tour player STBS - Who is the most famous professional player you have played or met? (can be modern or older era) SD - Nearly met Joe Davis STBS - Who is your favourite TV commentator? SD - Couldn''t possibly say STBS - What is your Favourite professional player and why? SD - I don''t have a favourite player really STBS - What has been the most memorable snooker match you have ever seen? SD - Watching Terry Griffiths collapse from 8-2 in front against Rex Williams in the UK qualifiers in his first big event as a pro. The 1985 final I didn’t see as I had my eyes closed STBS -Who is the most under-rated player in professional snooker? SD - Probably Graeme Dott. STBS -Who is the best professional player in your view to have ever picked up a cue? SD - Either John Higgins, Stephen Hendry or Ronnie O''Sullivan. STBS - Funniest moment in your snooker experience? SD - A game of Poker Dice with Dennis Taylor, Willie Thorne and Rex Williams where we got Rex to believe that there were 5 aces in the box STBS - Who is your bogey player? SD - Currently me STBS - Do you have any snooker ambitions you still have not achieved? SD - To play Professional main tour Snooker at the age of 56 Images Courtesy of: Tai Chengzhe', '2014-01-01', false, 'Richard Pearson'),
  ('CUEVIEW - Steve Downing', 'cueview-steve-downing', 'Cue View', '[]'::jsonb, 'A name familiar with most snooker players in our beautiful county is Steve Downing, for all of you who know him you will know what a great player and prolific break builder and all round excellent player he is.', null, '"A pro came to practise at our club (he shall remain nameless) we had been out for a curry/beers the night before and the following day couldnt stop passing wind virtually everytime he leaned over the table, he thought it was highly funny.However the committee didnt and after a short time banned him from the club for life !!!! a bit harsh lol"', 'A name familiar with most snooker players in our beautiful county is Steve Downing, for all of you who know him you will know what a great player and prolific break builder and all round excellent player he is.

more Steve was more than happy to fill out one of our CueViews and we are also hoping he may write us a small amateur career profile sometime soon. Steve has played a lot of the pro''s in other leagues and exhibitions over the years (and beaten quite a few) he is also great friends with current pro Martin Gould. We also won''t forget that he played in our league 2 years ago and went unbeaten throughout the whole season winning just about everything he entered. - Cheers Steve. STBS - What is your full name please SD - Steve Downing STBS - Your Current Club/base SD - St Rumons Redruth STBS - Your Highest Break SD - 147 STBS - Are you Left/Right Handed or both SD - Right Hander STBS - Bio about yourself (in no more than 200 words) SD - Born an bred as a boy in the north east of england ( Hartlepool),lived in London for just over 10 years then moved to sunny Cornwall!!! Started off playing a bit of billiards then moved onto snooker. Moved to London in 1990 cue in hand.Lived just around the corner from Wembley, it was great for the masters every year lol.I moved to cornwall in 2002 for a totally different lifestyle, i thought that my snooker would stop as i thought that their cant be much snooker going on here, how wrong i was. STBS - What was your first ever memory of snooker? SD - Watching my uncle bob playing in the atheneaum in hartlepool.He was a proffesional billiards player and a very very good snooker player. STBS - At what age did you start playing snooker and why? SD - I started playing at about 13 after getting the bug from watching my uncle play,i would go to the club every saturday at first then every bit of free time as long as i had the cash for the meter i would be ther like a shot.My old club is still going and i visit when i can to see some old faces and have a game. STBS - What has been your greatest achievement in snooker? SD - There''s been a few, making a few 147s, beating gouldy balls in my last ever final in london, winning county snooker and billiards in the same year and representing my adopted county. STBS - Who is the most famous professional player you have played or met? (can be modern or older era) SD - I spent an evening practising with Alex Higgins sometime ago, that was interesting, and a legend. STBS - Who is your favourite TV commentator? SD - Got to say Neil Foulds as he is a pal of mine and we used to play at the same club in ealing STBS - What is your Favourite professional player and why? SD - Alex Higgins took the game to another level STBS - What has been the most memorable snooker match you have ever seen? SD - 1985 world final STBS -Who is the best player in the league? SD - st blazey, Barry mac/andy best ………mining league southworth/hurley/downing STBS -Who is the most under-rated player in the league? SD - st blazey, paul barron, think he is a good player and probably could get better if he wanted to! Mining league is deffo Jamie Reed, that boy pots balls that aint even on and is improving week by week, one to watch in the county STBS - Funniest moment in your snooker experience? SD - A pro came to practise at our club (he shall remain nameless) we had been out for a curry/beers the night before and the following day couldnt stop passing wind virtually everytime he leaned over the table, he thought it was highly funny.However the committee didnt and after a short time banned him from the club for life!!!! a bit harsh lol STBS - Who is your bogey player? SD - Not got one, would like one to motivate me a bit lol STBS - Do you have any snooker ambitions you still have not achieved? SD - I win the world snooker in sheffield most weeks, then have a nice bowl of cornflakes and go to work…………………….no ambitions. Images Courtesy of: Steve Downing', '2014-01-01', false, 'Richard Pearson'),
  ('CUEVIEW - Stuart Bingham Exclusive', 'cueview-stuart-bingham-exclusive', 'Cue View', '[]'::jsonb, 'Stuart Bingham the current provisional world number 10 has kindly spoken with us and supplied us with an exclusive CueView interview', null, '"I remember farting at the Crucible playing Jimmy White in 2000. Jimmy and the ref (Eirian Williams I think) and the front 2 rows got the full brunt of it! Lol. "', 'Stuart Bingham the current provisional world number 10 has kindly spoken with us and supplied us with an exclusive CueView interview

more STBS - What is your full name please SB - Stuart Bingham STBS - Your Current Club/base SB - Rayleigh Lanes Snooker Club, Rayleigh, Essex. STBS - Your Highest Break SB - 147 x 175+ (3 in pro Events) STBS - Are you Left/Right Handed or both SB - Right handed. STBS - Bio about yourself (in no more than 200 words) SB - Try to be very professional about whatever I do. Dedicated, hard worker and try 100% all the time. I''m sport mad and use to love golf but since having a family that''s all changed. Not bothered about anything other than spending quality time with my family when I''m not playing snooker. Love winding people up and having a laugh. STBS - What was your first ever memory of snooker? SB - Playing snooker with my dad at a holiday camp and I had to use a milk crate, I was about 4! STBS - At what age did you start playing snooker and why? SB - I started playing properly at the age of 13! I went down the local club with my brother and 2 of his mates just to make it a doubles game. The manager of the club (Dave Meads, my first coach) notice me and offered coaching because he said he see some potential. The rest is history!;-) STBS - What has been your greatest achievement in snooker? SB - Obviously winning the Goldfields Australian Open in 2011. STBS - Who is the most famous professional player you have played or met? (can be modern or older era) SB - It''s gotta be Steve Davis on both counts. I call him my dad as he''s from Essex and he''s old enough to be my dad. A great and funny guy. STBS - Who is your favourite TV commentator? SB - It''s gotta be my dad, Steve Davis. His knowledge is second to none. STBS - What is your Favourite professional player and why? SB - Stephen Hendry, he''s broke all the records and he''s just a ruthless born winner. STBS - What has been the most memorable snooker match you have ever seen? SB - I suppose everyone''s has gotta be the 1985 world final but I was only 9! But 1 always sticks in my mind is the Masters final between Ronnie O''Sullivan and Paul Hunter! Just an unbelievable outcome and most probably the only person who could have done that against Ronnie. STBS -Who is the most under-rated player in professional snooker? SB - I think Graeme Dott is under rated, he doesn''t get the recognition he deserves! Other than him, then it''s me! Lol. STBS - Funniest moment in your snooker experience? SB - I remember farting at the Crucible playing Jimmy White in 2000. Jimmy and the ref (Eirian Williams I think) and the front 2 rows got the full brunt of it! Lol. STBS - Who is your bogey player? SB - It use to be Robin Hull, he always played well against me and use to thrash me every time! STBS - Do you have any snooker ambitions you still have not achieved? SB - The obvious ones are to be world number 1 and world champ but to win another tournament would be great as there''s so many good players these days! But someone once said to me "if you can get your mortgage paid and still be healthy out of your profession then you have done well" I''m still working on it! Lol. Images Courtesy of: Action Images & Monique Limbos', '2014-01-01', false, 'Richard Pearson'),
  ('CUEVIEW - Terry Camilleri Exclusive', 'cueview-terry-camilleri-exclusive', 'Cue View', '[]'::jsonb, 'To continue our referee CueView theme today we interviewed top pro referee Terry Camilleri, lovely guy and top referee from Malta!', null, 'I am maltese married to Elaine with two kids Thomas and Emma. I have been a Referee since 1990 and became a Pro Ref in 1998. I have refereed finals of Malta Cup twice, Shanghai Masters, Welsh Open and this year''s Masters. I had the opportunity to referee 3 max 147 breaks on TV, with Ali Carter and Stephen Hendry at the World championships and John Higgins at the UK Championships."', 'To continue our referee CueView theme today we interviewed top pro referee Terry Camilleri, lovely guy and top referee from Malta!

more STBS - What is your full name please TC - Terry Camilleri STBS - Bio about yourself (in no more than 200 words) TC - I am maltese married to Elaine with two kids Thomas and Emma. I have been a Referee since 1990 and became a Pro Ref in 1998. I have refereed finals of Malta Cup twice, Shanghai Masters, Welsh Open and this year''s Masters. I had the opportunity to referee 3 max 147 breaks on TV, with Ali Carter and Stephen Hendry at the World championships and John Higgins at the UK Championships. STBS - Have you ever visited any of the clubs in the St Blazey & District Snooker League (Cornwall) before? TC - No unfortunatly I have not been to Cornwell. My favourite place has to be Sheffield World Championships. STBS - Do you play any snooker or pool? TC - I do play a bit of both when I have time! STBS - Have you always wanted to be a snooker/pool referee? TC - No I used to be a snooker player but then changed direction to refereeing. STBS - Who is your favourite TV commentator? TC - Dennis Taylor STBS - Who is your favourite professional player and why? TC - No one in particular. STBS -Do you think the players give the referees the respect they deserve? TC - Yes they do which I think we Referees do as well. STBS - If you could change one rule in snooker, which one would it be? TC - I would change the miss rule. STBS - Has there ever been a scenario where you didn''t know the rule? TC - No for sure. STBS - What is the hardest part of refereeing? TC - Keep concentrated in long matches. STBS - Do you have a favourite venue? TC - Sheffield World Championships STBS - What has been the most memorable snooker match your have refereed or seen? TC - Has to be my Masters Final. STBS - Funniest moment for you so far in your career? TC - Walking with the zip fly open! STBS - Do you have any ambitions as a referee you still have not achieved? TC - Obviously refereeing the World Championship Final. Images Courtesy of: Action Images', '2014-01-01', false, 'Richard Pearson'),
  ('CUEVIEW - Tony Chappel', 'cueview-tony-chappel', 'Cue View', '[]'::jsonb, 'Tony Chappel, the name rings a bell yes? Well it should do especially lately as Tony got to the final of the World Seniors Championship eventually coming up short against Nigel Bond', null, '"Professional from 1984 - 2000. Experienced great highs and some lows. This career gave me the opportunity to travel the world, but now i am a happily married, family man, who always has and always will love the game of snooker. "', 'Tony Chappel, the name rings a bell yes? Well it should do especially lately as Tony got to the final of the World Seniors Championship eventually coming up short against Nigel Bond

more Tony kindly agreed to answer our questions on the ever increasingly popular CUEVIEW feature - thank you Tony STBS - What is your full name please TC - My full name is Anthony Richard Chappel STBS - Your Current Club/base TC - Not tied to any club STBS - Your Highest Break (if 147 how many) TC - 147. 15 in total, 2 in competition STBS - Are you Left/Right Handed or both TC - Just right handed STBS - Bio about yourself (in no more than 200 words) TC - Professional from 1984 - 2000. Experienced great highs and some lows. This career gave me the opportunity to travel the world, but now i am a happily married, family man, who always has and always will love the game of snooker. STBS - What was your first ever memory of snooker? TC - At 11 years old. My parents ran a club. STBS - At what age did you start playing snooker and why? TC - At 11 years old. My parents ran a club. STBS - What has been your greatest achievement in snooker? TC - Semi-finals of China open 1990 STBS - Who is the most famous professional player you have played or met? (can be modern or older era) TC - Have met and played all top players during the 80''s and 90''s era. STBS - Who is your favourite TV commentator? TC - The late Ted Lowe STBS - What is your Favourite professional player and why? TC - Steve Daniels was my inspiration, for text book cue action and all round game. STBS - What has been the most memorable snooker match you have ever seen? TC - Jimmy White V Alex Higgins, 1982 world semi-finals. STBS - Do you have any snooker ambitions you still have not achieved? TC - Winning a ranking title was an ambition when i was Pro. STBS - Who is your bogey player? TC - Don''t have one. STBS - Funniest moment in your snooker experience? TC - Watching Alex Higgins playing with his leg in plaster. STBS - Who is the most under-rated player in professional snooker? TC - Graham Dot. Images Courtesy of: Action Images', '2014-01-01', false, 'Richard Pearson'),
  ('CUEVIEW - Willie Thorne Exclusive', 'cueview-willie-thorne-exclusive', 'Cue View', '[]'::jsonb, 'Today I was lucky enough to chat on the phone to the legend that is ''The Great WT'' snookers Mr Maximum, yes Willie Thorne. Willie was very candid with his answers and we hope you enjoy the interview as much as I did…', null, 'Willie Thorne on Jonathan Barron... "One of the best talented amateur players I have ever seen, but he never really seemed to want to turn pro, I used to go down to Cornwall quite a lot playing the likes of Charlie Gay and various exhibitions, Jonathan always seem to be a bit shy really, but I do have some really fond memories of Cornwall that''s for sure."', 'Today I was lucky enough to chat on the phone to the legend that is ''The Great WT'' snookers Mr Maximum, yes Willie Thorne. Willie was very candid with his answers and we hope you enjoy the interview as much as I did talking to him.

more STBS - What is your full name please WT - Willie Thorne STBS - Your Highest Break WT - 198 - but it''s 14 years since i played STBS - Are you Left/Right Handed or both WT - I''m right handed and couldn''t make a 20 break left handed STBS - Bio about yourself (in no more than 200 words) WT - Born in Anstey, Leicester in March of 1954, snooker was introduced into Willie''s life from a young age. When his brother Malcolm asked for a 6ft x 3ft snooker table for Christmas, in true brotherly style, Willie started playing the game at every opportunity, quickly becoming obsessed. As he perfected his game, his parents were supportive of his passion; his mother bought him his first snooker cue when Willie turned 14, a cue he continued to use, with adaptations, throughout his entire career. Honing his skills as a junior player, Thorne became national under-16 champion at both snooker and English billiards in 1970. Since then, Willie''s snooker playing career became a certainty. In a career spanning three decades, Willie can now boast holding a total of 14 tournament victories worldwide. "The Great WT", as he is affectionately known, was a regular in the Top 16 World Ranking players for well over a decade and is one of the top record breakers for the highest number of 147 breaks in the history of snooker (190), earning him his recognisable nickname "Mr Maximum". Willie has definitely established himself as one of the greatest characters of snooker for over 25 years. STBS - What was your first ever memory of snooker? WT - Purely by accident really, my brother had a table given to him as a christmas present, i hadn''t really noticed the game really till then and we started playing together. My father worked in amine and the mine closed, so he took a job at the local conservative club, I went with him and started playing on full size tables. STBS - At what age did you start playing snooker and why? WT - I started playing at about 13 and then I started entering the boys championships at 14. STBS - What has been your greatest achievement in snooker? WT - Winning my first major tournament which was the mercantile credit classic, i only won the won ranking event but won 14 other tournaments around the world, I could seem to win abroad but not in this country. STBS - Who is the most famous professional player you have played or met? (can be modern or older era) WT - The player with the most ability is undoubtably Ronnie O''Sullivan, the best break builder I have ever seen was Stephen Hendry, and the best match player is Steve Davis I think if they all played there very best then Ronnie would win, although its difficult to say as they all played in different eras STBS - Who is your favourite TV commentator? WT - Neal Foulds, well that''s not fair I love them all really, all the people I work with:-) STBS - What has been the most memorable snooker match you have ever seen? WT - There have been so many really, playing wise it was the UK final when I let 13-8 and got beat 16-14. There have been so many matches that have been superb so it''s a hard one to call but if I had to it would be the final of the Charity Challenge Birmingham, Ronnie O''Sullivan v Stephen Hendry, Ronnie was 8-2 behind and levelled at 8-8 and then Hendry made a 147 in the final frame to win. STBS -Who is the most under-rated player in professional snooker? WT - Well Stuart Bingham was until just recently, was always a class player but had never really got the results he wanted until the last few tournaments really, other players that spring to mind hmmm I suppose Jimmy White obviously all those world finals and never won the world championship. STBS - Funniest moment in your snooker experience? WT - That has to be Bill Werbenik when he was playing on the opposite table to me and his pants split, and he doesn''t wear any underwear soooo, that would be censored these days STBS - Who is your bogey player? WT - Probably Doug Mountjoy, I played Terry Griffiths about 10 times and lost to him once, Mountjoy played Griffiths I don''t know how many times and beat him, but I played Mountjoy 3 times and lost every one, there is no form line to that is there really. STBS - What is your favourite Professional and why? WT - When Ronnie O''Sullivan is playing I prefer to watch him play but he is such a genius, I like working with Shaun Murphy, done a bit of coaching with him, and enjoy watching him play. But commentating and watching wise it has to be Ronnie O''Sullivan. Images Courtesy of: Willie Thorne', '2014-01-01', false, 'Richard Pearson'),
  ('CUEVIEW – Pankaj Advani Exclusive', 'cueview-pankaj-advani-exclusive', 'Cue View', '[]'::jsonb, 'For all those of you who don''t recognise this name, well sit up and listen. Pankaj Advani is the current World Billiards Champion, not to mention he has won this title 8 times now, beating all time Billiards greats…', null, '"During my first media interaction ever, on being asked what I wanted to become when I grew up, replied, “A businessman.” Then, as an afterthought, added, “I would also like to be a world champion.” Innocent words that became reality in less than 8 years!"', 'For all those of you who don''t recognise this name, well sit up and listen. Pankaj Advani is the current World Billiards Champion, not to mention he has won this title 8 times now, beating all time Billiards greats of the game including Mike Russell

more Pankaj has recently joined the pro snooker circuit and he took the time and trouble whilst jetting around the world to fill in one of our exclusive CueVew interviews - we hope you enjoy, and remember the name Pankaj Advani. STBS - What is your full name please PA - Pankaj Advani STBS - Your Current Club/base PA - Sheffield. World Snooker Academy STBS - Your Highest Break PA - 143 STBS - Are you Left/Right Handed or both PA - I''m right handed. STBS - Bio about Pankaj (in no more than 200 words) PA - Born in Pune on 24 July 1985, Pankaj spent the first five years of his life in Kuwait with his parents –Arjan and Kajal and elder brother Shree. The family migrated to Bangalore after the Iraqi invasion and has been there ever since, except for his father who passed away when Pankaj was only six years old. Pankaj and Shree studied at the Frank Anthony Public School, Bangalore and both went on to become Head Boys of the school. Pankaj was too soft-hearted to report students to the principal when they, for instance, forgot to wear their house-badges. Instead, he would give them money to quickly buy the badges from the school shop. He was not around during the Annual Day or Sports Day as he was busy competing at the 2002 Asian Games in Korea. However, he scored a cool distinction in both ICSE and ISC board exams. But how did Pankaj begin his foray into the world of cue sport? He did it at the age of ten, courtesy his brother Shree. He would accompany Shree to the snooker parlour close to their house every day after school. For a few weeks, he just watched Shree play with his friends. Then one day he begged to be allowed to play. On his very first attempt, he pocketed the red ball and then on, he was hooked to the game. The following year, he won his first State title by beating his brother-cum-mentor in the finals. During his first media interaction ever, Pankaj, on being asked what he wanted to become when he grew up, replied, “A businessman.” Then, as an afterthought, added, “I would also like to be a world champion.” Innocent words that became reality in less than 8 years! Such are the ways of the Power of Attraction that world-renowned Snooker wizard Arvind Savur spotted this talent at a young age and took him under his wing. Blessed with passion, natural ability and dedication for the sport, Pankaj sent out a warning signal to all Indian and International players of his arrival on the scene. Mr. Savur, the father of modern snooker, promised the family that he would make Pankaj a world champion, but he too was pleasantly surprised by what was to come. Pankaj went on to complete his Bachelor Degree in Commerce with a 1st Class at SBM Jain College, Bangalore. He was only 6 months into college when he won the Men’s World Snooker Championship in China at the age of 18. This was the first of his 8 world titles. STBS - What was your first ever memory of snooker? PA - Watching my brother Shree play snooker at a local club in the neighbourhood. He used to go there every evening after school and out of curiosity I followed him. STBS - At what age did you start playing snooker and why? PA - At the age of 10, when Shree taught me how to play. I was fascinated with the colour the sport had to offer. I was tempted to play and after learning I got the very first pot in! STBS - What has been your greatest achievement in snooker? PA - IBSF World Snooker Champion 2003 STBS - Who is the most famous professional player you have played or met? (can be modern or older era) PA - Steve Davis STBS - Who is your favourite TV commentator? PA - I''ve watched and played a lot of snooker, but not listened to the commentary too much. STBS - What is your Favourite professional player and why? PA - Ronnie, Hendry and Higgins. Talent and perseverance. STBS - What has been the most memorable snooker match you have ever seen? PA - Ronnie''s World Championship Finals match this year. STBS -Who is the most under-rated player in professional snooker? PA - It''s too early to give a name as I''ve just started on the Main Tour. STBS - Funniest moment in your snooker experience? PA - I played a hard shot and the ball jumped off and landed on another table where the player was on a century. Oops! STBS - Who is your bogey player? PA - Just started playing the circuit. Hopefully won''t have any. STBS - Do you have any snooker ambitions you still have not achieved? PA - There''s lots to achieve. I''m taking it one step at a time. Images Courtesy of: Pankaj Advani', '2014-01-01', false, 'Richard Pearson'),
  ('Captain Lands German Crown', 'captain-lands-german-crown', 'Professional Snooker', '[]'::jsonb, 'Ali Carter came from 5-3 down to beat Marco Fu 9-6 to win his third world ranking title at the Betfair German Masters in Berlin.', null, '"It was a tough day, we both wanted to win so badly," said Carter, who nearly had to play his first match in Berlin without his cue as it failed to arrive on his flight to Germany and was only delivered to the venue an hour before he took to the baize. "We wanted to put on a good show for the crowd because it''s such a magnifient arena so I''m just delighted to come out a winner."', 'Ali Carter came from 5-3 down to beat Marco Fu 9-6 to win his third world ranking title at the Betfair German Masters in Berlin.

more Carter dominated the evening session in the German capital to take the 60,000 Euro top prize and add to the ranking titles he won at the 2009 Welsh Open and 2010 Shanghai Masters. Hong Kong''s 35-year-old Fu looked the stronger player in the early stages but struggled with his safety and potting at the business end. A crowd of over 2,000 fans rose to salute 33-year-old Carter as he paraded the trophy. Snooker is clearly booming in Germany and there were excellent crowds throughout the week at the Tempodrom, which is considered by many players the best venue on the circuit. For the past decade, Carter has suffered from Crohn''s disease, and just 14 months ago he announced his intention to quit snooker, believing that the painful effects of the illness and a loss of form were dragging him down in a vicious circle. A change of diet helped him combat the disease and his game improved sharply as he reached the final of the World Championship, losing to Ronnie O''Sullivan. At the UK Championship in December, after a cruel 9-8 semi-final defeat against Shaun Murphy - from 8-4 ahead - Carter broke down in tears in his post-match press conference as he admitted that Crohn''s remains an obdurate factor in his personal and professional life. So tonight''s victory brings a measure of redemption for the player nicknamed The Captain as he proved to himself that he can still win major titles and his decision to persevere with his snooker career was correct. He is up to number 11 in the world and can look forward to the rest of the season confident of adding more silverware. Carter was 5-3 down after the first session but immediately swung the momentum his way with a fantastic start this evening, knocking in breaks of 116 and 121, his first centuries of the tournament. He also dominated frame 11 to take the lead for the first time at 6-5. Fu, who was seeking his second ranking title having won the 2007 Grand Prix, made 48 in frame 12 before playing safe on the last red. Carter potted the red but missed the brown and his opponent was able to level the tie at the mid-session interval. In the 13th, Carter made 32 then Fu replied with 31 before running out of position. The Asian cueman then played a weak safety to let Carter in for an excellent 71. Frame 14 was a scrappy one but Carter didn''t mind as he took it with a run of 41 to lead 8-6. Carter missed two tricky pots early in the 15th, but when Fu failed on a slow-rolled red to a centre pocket, the Essex man took his chance. A break of 39 put him 52 ahead with three reds left, and when Fu missed again, Carter closed out victory. "It was a tough day, we both wanted to win so badly," said Carter, who nearly had to play his first match in Berlin without his cue as it failed to arrive on his flight to Germany and was only delivered to the venue an hour before he took to the baize. "We wanted to put on a good show for the crowd because it''s such a magnifient arena so I''m just delighted to come out a winner. "It hasn''t been an easy time for me but I have given it my all and things have turned around massively, which makes it very satisfying. It has been a long time coming and I''ve been through tough times. A year ago I didn''t want to be playing. I had a big disappointment at the UK losing to Shaun, because I felt could win it. That makes it all the sweeter because life makes you wait and makes you want it even more when you get hurt. "Today wasn''t pretty but I got the job done. It''s a relief to win and get another ranking title on the board. In the evening session I tried to change my mindset and think back to the Welsh Open final when I was 5-2 down to Joe Swail and came to back to win 9-5. It''s tough to win tournaments but I''ve done it so I''m happy. "Sometimes I forget what a good player I am. The likes of Mark selby and Neil Robertson are winning titles but I when I beat Neil yesterday I told myself that I can be in that category." Fu, who has now lost in three ranking finals as well as the 2011 Masters, said: "I didn''t have many chances tonight. Every time I came to the table I was faced with a tough shot. Ali played very well so all credit to him. It was nice to be in a final again as the crowd was great - hopefully I can come back next year and win it." Article courtesy of the World Snooker Images Courtesy of: Monique Limbos', '2014-01-01', false, 'Richard Pearson'),
  ('Carter Captures World Open', 'carter-captures-world-open', 'Professional Snooker', '[]'::jsonb, 'Ali Carter won the fourth ranking title of his career by beating Joe Perry 10-8 in the final of the Hanteng Autos World Open in Yushan, China.', null, '“I’m delighted – there was so much riding on today, winning a ranking event as well as my top 16 place,” said Carter. “I have been focused all week and to come out the winner is very special. It has been a great week for me.', 'Ali Carter won the fourth ranking title of his career by beating Joe Perry 10-8 in the final of the Hanteng Autos World Open in Yushan, China.

more Carter won six consecutive frames to go 8-3 ahead, and despite an exciting late rally from his opponent, he secured the match in frame 18 to capture the £90,000 top prize. Victory sees the 37-year-old from Chelmsford jump 15 places in the world rankings to number 16. Carter’s previous ranking titles came at the 2009 Welsh Open, 2010 Shanghai Masters and 2013 German Masters. Since then he has battled bravely against testicular cancer and a tumour on his lung, as well as the ongoing effects of Crohn’s Disease. The popular cueman made an emotional return to the circuit late in 2014 and went on to win the Paul Hunter Classic – a minor ranking event – last year. Today’s success is another just reward for his tenacity and determination throughout. This triumph, in his seventh career ranking final, also gives Carter a place in the Champion of Champions in Coventry in November and almost certainly the World Grand Prix and Players Championship later in the season. Perry was playing in his fourth ranking final and looking for his second title having landed his first at the Players Championship last year. The 41-year-old produced stunning snooker to beat Neil Robertson 6-2 in the semi-finals on Saturday, but only showed patches of that form today. His runner-up prize is £40,000 and he stays 11th in the world. Perry held leads of 2-1 and 3-2 early in the final, making breaks of 54, 56 and 78. But it was Carter who dominated the middle part of the match as he reeled off six frames on the spin. Runs of 80, 54, 91, 53, 61 and a superb 70 clearance in frame 11 helped the Essex potter surge 8-3 ahead. Cambridgeshire’s Perry stopped the rot in a scrappy 12th then made an excellent 131 in the 13th to close to 8-5. Breaks of 37 and 31 helped Carter win the next, then Perry made a 106 to claw back to 9-6. Carter had a match winning chance in frame 16 but missed the last red with the rest when trailing by 11 points, allowing his opponent to clear up and reduce the deficit. And Perry continued to gather momentum in the next as a run of 92 saw him draw within one frame at 9-8. But two-time World Championship finalist Carter withstood the pressure and finished in style with a break of 127. “I’m delighted – there was so much riding on today, winning a ranking event as well as my top 16 place,” said Carter. “I have been focused all week and to come out the winner is very special. It has been a great week for me. “Today’s match was very good. There were some big breaks and some scrappy frames as well. Joe might feel he lost the match in the first session, but then he played really well to come back at me. I knew I had to kill the match off in one visit so it was pleasing to do that in the end. “I have been through a lot over the last couple of years so to get back into the top 16 is a huge achievement.” Perry said: “I struggled all day, I didn’t feel comfortable. I was battling against my cue action. I only started to play when the match was over and I made a game of it. But it’s the worst I have played for a long time and I’m really disappointed in myself. “I’ve had a good tournament and produced some good performances but I saved the worst until last. Ali played better than me and made less mistakes. I had more than enough chances.” Article & Images courtesy of the World Snooker', '2014-01-01', false, 'Richard Pearson'),
  ('Carter wins Paul Hunter Classic', 'carter-wins-paul-hunter-classic', 'Professional Snooker', '[]'::jsonb, 'Ali Carter won his first professional tournament since successfully battling cancer, beating Shaun Murphy 4-3 in the final of the Paul Hunter Classic.', null, 'I’ve had a tough couple of years, to put it mildly, so it’s an unbelievable feeling to win,” said Carter. “I just tried to keep myself in the moment and not think about winning. I was delighted that when I got my chance in the last frame I managed to clear up.', 'Ali Carter won his first professional tournament since successfully battling cancer, beating Shaun Murphy 4-3 in the final of the Paul Hunter Classic.

more Carter won a Kreativ Dental Clinic European Tour event for the first time with triumph over Murphy in an exciting final in Fürth, Germany. The victory is worth 25,000 Euros and a magnificent new trophy supplied by Waterford Crystal, but far more significant for Carter is the knowledge that he still has the game and temperament to win titles at the top level. The 36-year-old from Chelmsford beat testicular cancer in 2013, as well as a tumour on his lung last year which required several cycles of chemotherapy to overcome. Carter, who also suffers from Crohn’s disease, missed a series of tournaments last season and saw his world ranking drop to 29th as a result. But he is now on the right path on and off the table and the three-time ranking event winner will believe he can regain a place among snooker’s elite. Fittingly, his return to the winner’s podium came at a tournament named after Paul Hunter, who died of cancer in 2006. Carter built a 3-1 lead in the final with top breaks of 61 and 54, Murphy’s only response coming with a run of 72 in the second frame. Masters champion Murphy took the fifth with an 83 then came from 56-7 down to nick the next, sealing it with a green-to-black clearance. But two-time World finalist Carter was not to be denied as he won the deciding frame with a superb break of 95 to win his first pro title since the 2013 German Masters. “I’ve had a tough couple of years, to put it mildly, so it’s an unbelievable feeling to win,” said Carter. “I just tried to keep myself in the moment and not think about winning. I was delighted that when I got my chance in the last frame I managed to clear up. “It means so much to win this event, especially after what Paul went through and what I went through, I was just lucky to get away with it.” Earlier in the semi-finals, Carter beat Michael Holt 4-2 while Murphy edged out Mark King 4-3. The Kreativ Dental Clinic European Tour is a series of six events across the continent, with the top 24 on the final Order of Merit to qualify for the Players Championship. The next event is the Ruhr Open in Mülheim, Germany from October 7-11. Article & Images courtesy of the World Snooker', '2014-01-01', false, 'Richard Pearson'),
  ('Clean sweep for Meva''s ''B'' boys', 'clean-sweep-for-mevas-b-boys', 'Match Reports', '[]'::jsonb, 'Mevagissey ‘B’ got a massive full house against their ‘D’ team to really give them hope of not being relegated.', null, 'Bugle ‘B’ had a terrific 4-1 home win over Bethel ‘A’ whose only success came from Andy Peers. That result almost secures at least a runners-up spot for Bugle ‘A’ following their 3-2 win at St Blazey.', 'Mevagissey ‘B’ got a massive full house against their ‘D’ team to really give them hope of not being relegated.

more The result leaves their opponents needing two big results in their remaining games in their quest to survive. Comprehensive wins for Nathan Shaw, Matt Rowe, Pete Chambers, who knocked in a fine 38 break and Mark Gregory, along with Ben Rothwell’s close victory over Rich Lakeman got them home. Mevagissey ‘D’ only took one point at home to St Neot in a re-arranged game on Monday through George Lory. But those four points along with a good 3-2 home win over champions elect Tregonissey ‘A’ has lifted Steve Courts team to fourth place only one point behind Bethel ‘A’. Andrew Pearce had two 40 breaks to beat Jason Simmons, followed by wins by the captain and Darren Lock, with Chris Stephenson and Ryan Bilson picking up the last two frames. Due to sickness Mevagissey ‘A’ could only raise three people to play at Pelynt and it didn’t get any better for them with Len Flower defeating Paul Williams, Andy Parnell getting the better of Matt Mills and John Daniells blackball victory over Louise Witerburn with walkovers for Richard Broad and Phil Ormond. After that game the Seniors final was played between Len and Phil. The first four frames were shared with Len making a 30 break in the second frame and he managed to win the last to take the title. Bugle ‘B’ had a terrific 4-1 home win over Bethel ‘A’ whose only success came from Andy Peers. That result almost secures at least a runners-up spot for Bugle ‘A’ following their 3-2 win at St Blazey. Nick Kendall beat Gary Spencer in the first frame with Jake Moore getting the better of Chris Morford to level things up. Ian Ball and then Andrew Best, who knocked in a fine 63 break, secured the win with Dean Willis getting the better of Paul Sturtridge for Blazey’s second point. It is as you were at the top of the Rees League as both Mevagissey ‘C’ and Bethel ‘C’ got three points from their games. Steve Williams and Lee McKinstry took two good frames for Gorran at Meva with Joe and Matt Chesterfield along with ‘The Predator’ Tregale securing the win. Bugle ‘C’ pushed the Bethel boys all the way with Mo Roscorla beating Paul Thomas and Roy Bayliss taking out Leigh Rosevear with Ben Stunnell, Howard Brett and Roger Smithson all enjoying wins. Graham Hoskin, Charles McMiram (walkover) and John Hancock all won as Lerryn took out St Stephen 3-2 with father and son Anthony and Rob Garside replied for the Saints. Alan Meades defeated Martin Isted for Tregonissey ‘C’s only point at home to Bethel ‘B’, who replied through Clive Stuthridge, Guy Buckle, Jim Tamblyn and Richard Bolt.

FULL RESULTS

Victory League: Pelynt 5 (L Flower, A Parnell, J Daniell, P Ormond w/o, R Broad w/o) Mevagissey ‘A’ 0, St Blazey 2 (N Kendall, D Willis) Bugle ‘A’ 3 (J Moore, I Ball, A Best (63)), St Neot 3 (A Pearce (44+40), S Courts, D Lock) Tregonissey ‘A’ 2 (C Stephenson, R Bilson), Mevagissey ‘B’ 5 (N Shaw, B Rothwell, M Rowe, P Chambers (38), M Gregory) Mevagissey ‘D’ 0, Bugle ‘B’ 4 (M Sturtridge, K Moore, C Rundle, D Rundle) Bethel ‘A’ 1 (A Peers). Rees Memorial League: Mevagissey ‘C’ 3 (J Chesterfield, M Chesterfield, D Tregale) Gorran 2 (S Williams, L McKinstry), Bethel ‘C’ 3 (B Stunnell, H Brett, R Smithson) Bugle ‘C’ 2 (M Roscorla, R Bayliss), Lerryn 3 (G Hoskin, C McMiram (w/o), J Hancock) St Stephen 2 (R Garside, A Garside), Tregonissey ‘C’ 1 (A Meades) Bethel ‘B’ 4 (C Stuthridge, G Buckle, J Tamblyn, R Bolt). Top breaks of the week: P Chambers 38, A Pearce 44,40, A Best 63 Additional Information League Tables Rankings Competitions Breaks Images Courtesy of: Richard Pearson', '2014-01-01', false, 'Richard Pearson'),
  ('Clean sweep for Treggy who stay top of the league', 'clean-sweep-for-treggy-who-stay-top-of-the-league', 'Match Reports', '[]'::jsonb, 'Tregonissey ‘A’ took all five points at St Stephen ‘A’ to stay clear at the top of the Victory League.', null, 'In the Rees League leaders Tregonissey ‘B’ dropped two vital points to St Stephen ‘B’. Justin and Mike Hooley along with Ryan Thomas got their wins with Terry Nicholls’ great win over Phil Hooley and Craig Nicholls, who has a walkover replying.', 'Tregonissey ‘A’ took all five points at St Stephen ‘A’ to stay clear at the top of the Victory League.

more Wins for Ryan Bilson, Barrie McIntosh, Jason Cocks, Martin Knight and Matt Woodward put them four ahead of Mevagissey ‘A’ who beat their ‘B’ team 4-1. Matt Rowe’s fine victory over Phil Staley was the ‘B’ teams only success as Paul Williams, Leighton Varcoe, Matt Mills and James Popplewell, who had a 47 break during his win, keeps the ‘A’ team right in the mix for honours. Bethel ‘A’ sit third after a close 3-2 home win over St Neot. Darren Lock sneaked past Garry Stephens in the opener which Andy Peers levelled taking the prized scalp of Steve Courts, further wins by Geoff Hawken and Leon Collard put Bethel 3-1 up but Cyril Dickenson’s fine potting display was too good for Matt Green to grab the second away point. Bugle ‘A’ dropped a couple of frames at St Blazey ‘A’ to stay fourth. Gary Spencer (Mike Hancock) and Ian Ball (Mickey Meares) put them on their way but Nick Kendall knocked in a 43 whilst beating Paul Sturtridge to pull one back. Andrew Best opened up a two-point gap after despatching Steward Dewings with Aiden Maxwell-Craddock getting the better of Jake Moore for the second home point. In the Rees League leaders Tregonissey ‘B’ dropped two vital points to St Stephen ‘B’. Justin and Mike Hooley along with Ryan Thomas got their wins with Terry Nicholls’ great win over Phil Hooley and Craig Nicholls, who has a walkover replying. Mark Ashton’s 40 clearance for Mevagissey ‘D’ equalled the Rees League’s highest break this season. He and Rich Lakeman, Rob Blamey and George Lory helped get the bragging right in the Meva derby as Matt Chesterfield beat Ian Latham for the ‘C’ team’s only success. Amanda Fleming and Michaela Edwards both played really well taking their frames against second placed Bethel ‘B’ who responded with wins for Guy Buckle, Richie Bolt and Clive Stuthridge but it was two welcome points for St Stephen ‘B. The Bethe derby had to be played at Tregonissey, due to overbooking of their home tables. Lee Searle, Dave Morshead and Jason Pascoe scored for the ‘D’ side with Leigh Rosevear and Roger Smithson replying.

FULL RESULTS

Victory League: St Blazey ‘A’ 2 (N Kendall, A Maxwell-Craddock) Bugle ‘A’ 3 (G Spencer, I Ball, A Best), Mevagissey ‘B’ 1 (M Rowe) Mevagissey ‘A’ 4 (J Popplewell (47), P Williams, L Varcoe, M Mills), St Stephen ‘A’ 0 Tregonissey ‘A’ 5 (R Bilson, B McIntosh, J Cocks, M Knight, M Woodward), Bethel ‘A’ 3 (A Peers, G Hawken, L Collard) St Neot 2 (D Lock, M Green). Rees Memorial League: Mevagissey ‘C’ 1 (M Chesterfield) Mevagissey ‘D’ 4 (R Lakeman, G Lory, R Blamey, M Ashton (40 clearance)), Tregonissey ‘B’ 3 (J Hooley, M Hooley, R Thomas) St Stephen ‘B’ 2 (T Nicholls, C Nicholls), Bethel ‘B’ 3 (G Buckle, R Bolt, C Stuthridge) Tregonissey ‘C’ 2 (A Fleming, M Edwards), Bethel ‘D’ 3 (L Searle, D Morshead, J Pascoe) Bethel ‘C’ 2 (L Rosevear, R Smithson). Additional Information League Tables Rankings Competitions Breaks Top breaks of the week: J Popplewell 47, N Kendall 43, M Ashton 40 The draw for the next round of all the competitions was made by Matt Rowe and Mark Gregory at Mevagissey Social Club. Seniors: Philip Ormand v Geoff Hawken, Leon Collard v Len Flower. Singles: Barrie McIntosh v Steve Courts, Ryan Bilson v James Popplewell, Gary Stephens v Andrew Best, Darren Lock v Andy Peers. Bill Toms: Barrie McIntosh v Adrian Bowyer, Darren Lock v Ryan Bilson, Jason Simmons v Andrew Best, Jason Cocks v Philip Hooley. Willie Thomas: Philip Hooley v Jim Tamblyn, Stacey Hancock v Leigh Rosevear, Clive Stuthridge v Justin Hooley, Courtney Crockford v George Lory. Doubles: J Popplewell and P Staley v M Knight and M Woodward, M Green and C Stuthridge v S Courts and D Lock, A Best and G Spencer v G Hawken and A Peers, G Stephens and R Opie v J Cocks and J Simmons. Team Pairs: Bugle ‘B’ v Bugle ‘A’, Bethel ‘A’ v Tregonissey ‘A’. To be played on Tuesday, February 7. Team Handicap: St Blazey ‘A’ v Bethel ‘C’ to be played on Tuesday, February 7, Bugle ‘B’ v Bethel ‘A’ date TBA. Images Courtesy of: Richard Pearson', '2014-01-01', false, 'Richard Pearson'),
  ('Close in every match in the Victory League', 'close-in-every-match-in-the-victory-league', 'Match Reports', '[]'::jsonb, 'The snooker season started with every match in the Victory League ending in an odd frame victory.', null, 'Len Flower and Phil Ormond got Pelynt’s points at Bugle ‘B’ – Keith and Jake Moore responded with a 32 break by Mark Sturtridge the deciding fact in the decider.', 'The snooker season started with every match in the Victory League ending in an odd frame victory.

more Defending champions Tregonissey ‘A’ lost out at Mevagissey ‘A’ where Phil Staley, Matt Mills and the comeback king Leighton Varcoe got the home points with Ryan Bilson, who knocked in a good 34 break, and Barrie McIntosh (walkover) responding. St Blazey ‘A’ pulled off a great win over their ‘B’ side with Mickey Meares (33), Nick Kendall and Stewart Dewings doing the damage. Mike Hancock had started all guns firing, knocking in a 54 but was outdone on the night as teammate Paul Baron had a 56 clearance. Promoted St Stephen ‘A’ picked up two handy points at St Neot through Anthony Garside and Anthony Harrison with Steve Courts, Cyril Dickenson and Darren Lock with a 44 replying. Len Flower and Phil Ormond got Pelynt’s points at Bugle ‘B’ – Keith and Jake Moore responded with a 32 break by Mark Sturtridge the deciding fact in the decider. Bethel ‘A’ started well at home to Mevagissey ‘B’ going 3-0 up through Gary Stephens, Andy Peers and Matt Green but the away side battled back with wins for Mark Gregory and Ben Rothwell, who potted two stupendous blacks to win a respotted frame. In the Rees League newcomers all ladies team Tregonissey ‘C’ had a baptism of fire at Mevagissey ‘D’ who claimed all five frames. Rich Lakeman, George Lory, Scott Mills and Rob Blamey were all victorious and also saw Ian Latham win on the black against Stacey Hancock. Bethel ‘B’ have started strongly with Guy Buckle, Jim Tamblyn and Richie Bolt and Clive Stuthridge all winning at St Stephen ‘B’ with Josh Doherty beating Martin Isted for the home point. Tregonissey ‘B’ are the new holders of the Runabout Shield and they held on to it by beating Mevagissey ‘C’ 3-2. Justin Hooley and Chris Robins, who edged past the predator gave Treggy a 2-0 lead. Ben Prynn took the third frame with Phil Hooley securing victory by beating Matt Chesterfield but brother Joe reversed the last, beating Mike Hooley to get Meva’s second point. All clubs should have received their competition sheets this week with all entries required to the secretary by September 23.

FULL RESULTS

Victory League: St Blazey ‘B’ 2 (M Hancock (54), P Barron (56 clearance) St Blazey ‘A’ 3 (M Meares (33), N Kendall, S Dewings), Mevagissey ‘A’ 3 (P Staley, M Mills, L Varcoe) Tregonissey ‘A’ 2 (R Bilson (34), B McIntosh (walkover), St Neot 3 (D Lock (44), S Courts, C Dickenson) St Stephen ‘A’ 2 (A Garside, A Harrison), Bugle ‘B’ 3 (K Moore, J Moore, M Strurtridge (32)) Pelynt 2 (L Flower, P Ormond), Bethel ‘A’ 3 (G Stephens, A Peers, M Green) Mevagissey ‘B’ 2 (M Gregory, B Rothwell). Rees Memorial League: Mevagissey ‘D’ 5 (R Lakeman, G Lory, I Latham, S Mills, R Blamey) Tregonissey ‘C’ 0, St Stephen ‘B’ 1 (J Doherty) Bethel ‘B’ 4 (J Tamblyn, G Buckle, R Bolt, C Stuthridge), Lerryn 2 (G Hoskin, J Stephens) Bethel ‘D’ 3 (D Morshead, R McMenemy, J Pasoce), Tregonissey ‘B’ 3 (J Hooley, C Robins, P Hooley) Mevagissey ‘C’ 2 (B Prynn, J Chesterfield). Additional Information League Tables Rankings Competitions Breaks Top breaks of the week: R Bilson 34, M Meares 33, M Hancock 54, P Baron 56 Images Courtesy of: Richard Pearson', '2014-01-01', false, 'Richard Pearson'),
